/**
 * BANNER de aviso durante el sismo: dice que pasa y, al escoger experiencia, el tiempo limite.
 */
import { MISSION_SECONDS } from '../config.js'
import { state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { steps } from '../steps/navigation.js'
import { quake } from '../systems/quake.js'

function bannerKind() {
    // al escoger experiencia (hub) el aviso y el tiempo limite ya van en su propia tarjeta del centro
    if (!quake.active || state.hideBanner || state.cur === 'hub') return ''
    return 'strong'
}
export function updateBanner() {
    let t =
        state.cur &&
        steps[state.cur] &&
        steps[state.cur].stage === 2 &&
        state.mode !== 'show' &&
        state.cur === 'mission'
            ? bannerKind()
            : ''
    if (t === state.lastBanner) return
    state.lastBanner = t
    let a = qs('#quakeBanner')
    if (!t) {
        a.hidden = true
        return
    }
    let o = content.banner[t]
    a.hidden = false
    a.className = t === 'strong' ? 'strong' : 'calm'
    a.innerHTML =
        '<h3>' +
        o.t +
        '</h3><p>' +
        o.s +
        '</p>' +
        (o.limit ? '<p class="blimit">' + o.limit.replace('{n}', MISSION_SECONDS) + '</p>' : '')
}
