/**
 * PASOS de la etapa DURANTE (parte 2): tamanos de mascotas.
 * Todo ocurre en la misma habitacion de las tres experiencias (misma luz y fondo), con el temblor mas suave.
 * Orden: explicacion (tarjeta casi transparente) -> la camara se acerca a la puerta, donde esperan Cacao y Nube ->
 * se escoge el perro o el gato -> (perro) se escoge su tamano y se pulsa Continuar -> se ve el cambio de tamano y la
 * informacion, con la mascota en el centro -> al verlo todo, el usuario llega por un lado, abre la puerta, sale con
 * sus mascotas y la puerta se cierra antes del fundido hacia la siguiente etapa.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { QUAKE } from '../config.js'
import { session, state } from '../core/state.js'
import { damp, qs, qsa } from '../core/utils.js'
import { content } from '../data/content.js'
import { goTo, steps, transitionTo } from './navigation.js'
import { setCameraMode, setOrbit } from '../systems/camera.js'
import { quake, startQuake } from '../systems/quake.js'
import { cat, dog, person, placePet, setPetMood, walkPath } from '../three/characters.js'
import { ellipsoid, place, roundedBox } from '../three/helpers.js'
import { world } from '../three/world.js'
import { addHotspot } from '../ui/hotspots.js'
import { showPanel } from '../ui/panels.js'
import { resetPerson } from './sofaScene.js'

const SIZE_KEYS = ['large', 'medium', 'cat']
const SOFT_SHAKE = 0.2 // el temblor de la camara en esta parte (1 = el de las experiencias)

// ---- Camara (orbita alrededor de un punto): vista de toda la habitacion y vistas de la puerta ----
const hubView = () => ({
    theta: 0.8,
    r: 19,
    h: 12,
    tx: 0,
    ty: 1,
    tz: 0,
    sx: 0,
    sy: innerWidth > 720 ? 2.6 : 3.6,
    amp: 0.12,
})
const roomCentered = () => ({ ...hubView(), sy: 0 }) // la habitacion en el centro de la pantalla
const AT_DOOR = { theta: 0, r: 5.4, h: 2.4, tx: -6.1, ty: 0.85, tz: 0.5, sx: 0, sy: 0.15, amp: 0 }
const sizeCam = hubView() // valores actuales: se acercan poco a poco a la meta
let camGoal = hubView()
function driveCamera(dt) {
    Object.keys(camGoal).forEach((key) => (sizeCam[key] = damp(sizeCam[key], camGoal[key], 2.2, dt)))
    setOrbit({ ...sizeCam, speed: 0.09 })
}

// ---- Mascotas junto a la puerta (pared izquierda: x -7.15, hueco de z -0.5 a 1.5) ----
const DOG_AT = { x: -6, z: -0.25 }
const CAT_AT = { x: -6, z: 1.25 }
const DOG_SCALE = { pick: 0.65, large: 0.82, medium: 0.56 } // se nota la diferencia, sin exagerar
const CAT_SCALE = 0.6
const FACING = 0.9 // de tres cuartos hacia la camara: se ven la cabeza y la cola
function placeAtDoor(dogScale = DOG_SCALE.pick) {
    placePet(dog, DOG_AT.x, 0, DOG_AT.z, FACING, dogScale)
    placePet(cat, CAT_AT.x, 0, CAT_AT.z, FACING, CAT_SCALE)
    dog.visible = cat.visible = true
    setPetMood(dog, { wag: 1.2, eyes: 1.05 })
    setPetMood(cat, { wag: 1.1, eyes: 1.05 })
}

/**
 * Puerta de salida: una puerta propia que gira sobre su bisagra (borde z = -0.5), con la pared quieta a su
 * alrededor, y un fondo oscuro detras del hueco. Reemplaza al panel de pared de la casa mientras dura esta parte.
 */
let exit = null
function exitDoor() {
    if (exit) return exit
    const group = new THREE.Group()
    group.position.set(-7.15, 0, -0.5) // bisagra
    group.add(place(roundedBox(0.1, 2.28, 1.96, 0.03, '#c48b5a'), 0, 1.14, 0.99))
    group.add(place(roundedBox(0.04, 1.8, 1.4, 0.02, '#b57b4b'), 0.06, 1.14, 0.99))
    group.add(place(ellipsoid(0.07, '#ffc24d'), 0.1, 1.1, 1.75))
    // el hueco de la puerta da a un lugar oscuro: un fondo grande detras
    const dark = place(roundedBox(0.2, 3.2, 6, 0.01, '#050d1f'), -9.8, 1.5, 0.5)
    group.visible = dark.visible = false
    world.root.add(group, dark) // dentro de la casa: tiemblan con ella
    exit = { group, dark }
    return exit
}

/** El sismo sigue, pero con un temblor suave; la luz y el fondo son los mismos de las tres experiencias. */
function softQuake() {
    if (!quake.active) startQuake()
    quake.shakeTarget = SOFT_SHAKE
    quake.target = QUAKE.intensity * 0.4 // el ambiente (luz, polvo, fondo) tambien se calma
    audio.duck(0.75) // la musica de esta parte se oye mejor
}

/** Entra al paso: camara orbital, temblor suave, la puerta propia cerrada y la camara hacia su meta. */
function setUpRoom(goal) {
    setCameraMode('orbit')
    person.visible = false
    const door = exitDoor()
    world.plug.visible = false
    door.group.visible = door.dark.visible = true
    door.group.rotation.y = 0
    softQuake()
    camGoal = goal
    state.curTick = driveCamera
    state.curExit = () => {
        door.group.visible = door.dark.visible = false
        world.plug.visible = true
        dog.visible = cat.visible = true
        resetPerson()
    }
}
const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}
const lerp = (a, b, k) => a + (b - a) * k

steps.sizeIntro = {
    stage: 2,
    w: 0.85,
    prev: 'hub',
    next: 'sizePick',
    enter() {
        Object.assign(sizeCam, hubView())
        setUpRoom(roomCentered()) // la habitacion baja al centro de la pantalla
        placeAtDoor()
        // la tarjeta es casi transparente y aparece con un desvanecimiento: se sigue viendo la habitacion
        showPanel({
            text: content.sizeIntro.text,
            cls: 'center soft',
            actions: [{ label: 'Continuar', fn: () => goTo('sizePick') }],
        })
    },
}

steps.sizePick = {
    stage: 2,
    w: 0.92,
    prev: 'sizeIntro',
    next: 'despIntro',
    enter() {
        setUpRoom({ ...AT_DOOR }) // la camara se acerca a la puerta
        placeAtDoor()
        const panel = showPanel({
            title: content.sizePick.title,
            html: '<p class="count"></p>',
            cls: 'top gentle',
            actions: [{ label: 'Continuar', fn: () => goTo('sizeOut') }],
        })
        // no hace falta verlos todos para continuar: solo se avisa cuantos faltan
        const missing = SIZE_KEYS.length - session.sizes.size
        qs('.count', panel).textContent =
            missing > 0
                ? 'Faltan ' + missing + ' tamaño' + (missing > 1 ? 's' : '') + ' por ver · toca uno'
                : 'Ya viste todos los tamaños'
        const narrow = innerWidth < 720
        // las tres opciones directamente, con relleno y al lado de su mascota: el perro grande y el mediano
        // (una sobre la otra) junto a Cacao, y el gato junto a Nube
        ;[
            { key: 'large', pet: dog, side: narrow ? 70 : 120, shift: -24 },
            { key: 'medium', pet: dog, side: narrow ? 70 : 120, shift: 24 },
            { key: 'cat', pet: cat, side: narrow ? -70 : -110, shift: 0 },
        ].forEach(({ key, pet, side, shift }) => {
            const seen = session.sizes.has(key)
            const pill = addHotspot({
                cls: 'pill',
                label: (seen ? '✓ ' : '') + content.sizes[key].name,
                anchor: pet.userData.anchors.head,
                onClick: () => goTo('sizeInfo', { key }),
            })
            pill.style.marginLeft = side + 'px'
            pill.style.marginTop = shift + 'px'
            pill.classList.toggle('seen', seen)
        })
    },
}

/** El tamano elegido: la mascota cambia de tamano en el centro de la pantalla y su informacion queda coordinada. */
steps.sizeInfo = {
    stage: 2,
    w: 0.97,
    prev: 'sizePick', // desde aqui se vuelve a las demas opciones de tamano
    next: 'despIntro',
    enter(e) {
        const key = e.key
        const info = content.sizes[key]
        session.sizes.add(key)
        const isCat = key === 'cat'
        const pet = isCat ? cat : dog
        const at = isCat ? CAT_AT : DOG_AT
        // la camara se acerca mas: la mascota queda a un lado (en medio de su mitad de la pantalla) y la informacion al otro
        setUpRoom({ ...AT_DOOR, r: 3.0, h: 1.3, tx: at.x - 0.1, ty: 0.5, tz: at.z, sx: -0.58, sy: 0 })
        placeAtDoor()
        ;(isCat ? dog : cat).visible = false
        showPanel({
            title: info.name,
            text: info.text,
            cls: 'top gentle',
            actions: [{ label: 'Ver otros tamaños', fn: () => goTo('sizePick') }],
        })
        const callouts = qs('#callouts')
        callouts.hidden = false
        callouts.className = 'near' // pegadas a la mascota, no en el borde de la pantalla
        callouts.innerHTML = info.items
            .map(
                (n, d) =>
                    '<div class="callout card" data-i="' +
                    d +
                    '"><div><h3>' +
                    n.t +
                    '</h3><p>' +
                    n.d +
                    '</p></div></div>',
            )
            .join('')
        // sin numeros sobre el cuerpo de la mascota: solo las notas, que se resaltan al tocarlas
        const select = (n) => {
            qsa('.callout', callouts).forEach((card, u) => card.classList.toggle('on', n === u))
            audio.ding()
        }
        qsa('.callout', callouts).forEach((card, d) => card.addEventListener('click', () => select(d)))
        select(0)
        // el perro pasa de su tamano normal al elegido, para que se vea el cambio
        let time = 0
        state.curTick = (dt) => {
            driveCamera(dt)
            time += dt
            if (!isCat) {
                // el perro pasa de su tamano normal al elegido (grande o mediano) para que se vea la diferencia
                const s = lerp(DOG_SCALE.pick, DOG_SCALE[key], ease((time - 0.5) / 1.2))
                dog.scale.set(s, s, s)
            }
        }
    },
}

/** Final de los tamanos: el usuario llega por un lado, abre la puerta, sale con sus mascotas y la cierra. */
steps.sizeOut = {
    stage: 2,
    w: 0.99,
    prev: 'sizePick',
    next: 'despIntro',
    enter() {
        setUpRoom({ ...AT_DOOR })
        placeAtDoor()
        const door = exitDoor().group
        const limbs = person.userData
        // el usuario entra por el lado (z grande, fuera de la pantalla) y se para frente a la puerta
        const SIDE = { x: -5.4, z: 5.3 }
        const FRONT = { x: -5.4, z: 0.5 }
        const WALK_IN = 2.5 // segundos
        const T_OPEN = 3.4 // empieza a abrir la puerta
        const OPEN_TIME = 1.4
        const T_OUT = T_OPEN + OPEN_TIME + 0.2 // salen las mascotas y el usuario
        const OUT_TIME = 2.2
        const T_CLOSE = T_OUT + OUT_TIME + 0.3
        const CLOSE_TIME = 1.2
        const T_END = T_CLOSE + CLOSE_TIME + 0.3
        person.scale.set(1, 1, 1)
        person.visible = true
        person.position.set(SIDE.x, 0, SIDE.z)
        person.rotation.y = Math.PI
        let time = 0
        let openSound = false
        let petsOut = false
        let closeSound = false
        let leaving = false
        state.curTick = (dt) => {
            driveCamera(dt)
            time += dt
            // llega caminando y se vuelve hacia la puerta
            if (time < WALK_IN) {
                const w = ease(time / WALK_IN)
                person.position.set(lerp(SIDE.x, FRONT.x, w), 0, lerp(SIDE.z, FRONT.z, w))
                const swing = Math.sin(time * 9) * 0.65
                limbs.legL.rotation.x = swing
                limbs.legR.rotation.x = -swing
                limbs.armL.rotation.x = -swing * 0.8
                limbs.armR.rotation.x = swing * 0.8
            } else if (time < T_OUT) {
                limbs.legL.rotation.x = limbs.legR.rotation.x = 0
                limbs.armL.rotation.x = 0
                person.rotation.y = lerp(Math.PI, Math.PI * 1.5, ease((time - WALK_IN) / 0.6)) // mira a la puerta (-x)
                limbs.armR.rotation.x = lerp(0, -1.3, ease((time - T_OPEN + 0.5) / 0.5)) // estira la mano
            }
            // abre la puerta (gira hacia afuera)
            if (time > T_OPEN && time < T_CLOSE) {
                if (!openSound) {
                    openSound = true
                    audio.creak()
                }
                door.rotation.y = -1.45 * ease((time - T_OPEN) / OPEN_TIME)
            }
            // salen juntos: Cacao, el usuario y Nube
            if (time > T_OUT && !petsOut) {
                petsOut = true
                setPetMood(dog, { wag: 2.6, eyes: 1.1 })
                setPetMood(cat, { wag: 2.4, eyes: 1.1 })
                walkPath(dog, [{ x: -7, z: DOG_AT.z + 0.2 }, { x: -9, z: DOG_AT.z + 0.2, ry: -Math.PI / 2 }], 2.1)
                walkPath(cat, [{ x: -7, z: CAT_AT.z - 0.2 }, { x: -9, z: CAT_AT.z - 0.2, ry: -Math.PI / 2 }], 1.9)
                audio.bark()
            }
            if (time > T_OUT && time < T_CLOSE) {
                const w = ease((time - T_OUT) / OUT_TIME)
                person.position.set(lerp(FRONT.x, -9.2, w), 0, 0.5)
                person.rotation.y = -Math.PI / 2
                const swing = w > 0 && w < 1 ? Math.sin(time * 9) * 0.65 : 0
                limbs.legL.rotation.x = swing
                limbs.legR.rotation.x = -swing
                limbs.armL.rotation.x = -swing * 0.8
                limbs.armR.rotation.x = swing * 0.8
            }
            // al cruzar la pared ya estan afuera: dejan de verse
            if (person.position.x < -7.35) person.visible = false
            if (dog.position.x < -7.35) dog.visible = false
            if (cat.position.x < -7.35) cat.visible = false
            // cierra la puerta
            if (time > T_CLOSE) {
                if (!closeSound) {
                    closeSound = true
                    audio.creak()
                }
                door.rotation.y = -1.45 * (1 - ease((time - T_CLOSE) / CLOSE_TIME))
            }
            // y la escena se desvanece, con calma, hacia la siguiente etapa
            if (time > T_END && !leaving) {
                leaving = true
                transitionTo('despIntro', null, 1800)
            }
        }
    },
}
