/**
 * SISMO: intensidad constante (quake.k) que controla el audio y las sacudidas.
 */
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { QUAKE } from '../config.js'
import { damp, qs } from '../core/utils.js'
import { debris, dropBooks } from './quakeEffects.js'

export const quake = {
    active: false,
    t: 0,
    k: 0,
    target: 0,
    alarmT: 0, // segundos que lleva sonando la alarma
    shakeTarget: 1, // 0..1: cuanto tiembla la camara (la luz y el polvo no cambian)
    shakeK: 0, // sacudida suavizada = k * shake
    shake: 1,
}
export function startQuake() {
    quake.active = true
    quake.t = 0
    quake.alarmT = 0
    quake.target = QUAKE.intensity
    quake.shakeTarget = 1
    audio.rumble(0.6)
    audio.duck(0.4)
    audio.crash()
    dropBooks(99)
    audio.alarmSet(QUAKE.alarmVolume)
    state.onQuakePhase()
}
export function stopQuake() {
    quake.active = false
    quake.target = 0
    quake.shakeTarget = 1
    audio.rumble(0)
    audio.duck(1)
    audio.alarmSet(0)
    debris.forEach((e) => {
        e.st = 0
        e.m.visible = false
    })
    state.onQuakePhase()
}
export function updateQuake(dt) {
    let t = state.mode === 'show'
    if (quake.active && !t) {
        quake.t += dt
        quake.alarmT += dt
        if (quake.shake > 0.5 && Math.random() < dt * 0.6) {
            audio.creak()
        }
    }
    let a = quake.active && !t ? quake.target : 0
    quake.k = damp(quake.k, a, 3, dt)
    if (quake.k < 0.002) {
        quake.k = 0
    }
    quake.shake = damp(quake.shake, quake.shakeTarget, 2.5, dt)
    quake.shakeK = quake.k * quake.shake
    audio.rumble(quake.active && !t ? 0.6 * quake.shake : 0) // en los tamanos casi no se oye
    let o = quake.active && !t && quake.alarmT < QUAKE.alarmSeconds ? QUAKE.alarmVolume : 0
    if (o !== updateQuake.al) {
        updateQuake.al = o
        audio.alarmSet(o)
    }
    let s = qs('#alarmTag')
    if (s) {
        s.hidden = !(
            (quake.active && !t && state.mode !== 'orbit') ||
            (quake.active && state.mode === 'orbit' && state.cur === 'hub')
        )
    }
}
