/**
 * HOTSPOTS: botones HTML que siguen a puntos 3D, y la posicion del tooltip (#tip).
 */
import * as THREE from 'three'
import { state } from '../core/state.js'
import { clamp, createEl, qs } from '../core/utils.js'
import { camera } from '../three/renderer.js'

const hotspotList = []
export function positionTip() {
    let e = qs('#tip')
    if (!state.tipState || e.hidden) return
    let t = innerWidth,
        a = innerHeight
    if (t <= 820) {
        e.classList.add('dock')
        e.style.transform = ''
        return
    }
    e.classList.remove('dock')
    tmpVec.setFromMatrixPosition(state.tipState.anchor.matrixWorld).project(camera)
    let o = (tmpVec.x * 0.5 + 0.5) * t,
        s = (-tmpVec.y * 0.5 + 0.5) * a,
        r = e.offsetWidth,
        i = e.offsetHeight,
        n = Math.max(80, a * 0.15),
        d = o + n,
        u = false
    if (d + r > t - 16) {
        d = o - n - r
        u = true
    }
    d = clamp(d, 16, t - r - 16)
    let h = clamp(s - i / 2, 96, Math.max(96, a - i - 16))
    e.classList.toggle('left', u)
    e.style.setProperty('--ay', clamp(s - h, 18, i - 18) + 'px')
    e.style.transform = 'translate(' + d.toFixed(1) + 'px,' + h.toFixed(1) + 'px)'
}
export function clearHotspots() {
    hotspotList.forEach((e) => e.b.remove())
    hotspotList.length = 0
}
export function addHotspot(opts) {
    let t = createEl('button', 'hs ' + (opts.cls || 'dot'))
    t.type = 'button'
    t.setAttribute('aria-label', opts.aria || opts.label || 'Punto ' + (opts.num || ''))
    // pill = etiqueta con fondo; tag = texto suelto con una linea que termina en un punto sobre la mascota
    t.innerHTML =
        opts.cls === 'pill'
            ? '<span>' + opts.label + '</span>'
            : opts.cls === 'tag'
              ? '<i class="stem"></i><b>' + opts.label + '</b>'
              : '<i></i>' + (opts.num ? '<b>' + opts.num + '</b>' : '')
    if (opts.height) t.style.setProperty('--h', opts.height + 'px')
    t.addEventListener('click', (a) => {
        a.stopPropagation()
        if (opts.onClick) {
            opts.onClick(t)
        }
    })
    qs('#hotspots').appendChild(t)
    hotspotList.push({
        b: t,
        anchor: opts.anchor,
    })
    return t
}
const tmpVec = new THREE.Vector3()
export function updateHotspots() {
    let e = innerWidth,
        t = innerHeight
    hotspotList.forEach((a) => {
        tmpVec.setFromMatrixPosition(a.anchor.matrixWorld).project(camera)
        let o = tmpVec.z < 1
        a.b.style.display = o ? '' : 'none'
        if (o) {
            a.b.style.transform =
                'translate(' +
                ((tmpVec.x * 0.5 + 0.5) * e).toFixed(1) +
                'px,' +
                ((-tmpVec.y * 0.5 + 0.5) * t).toFixed(1) +
                'px) translate(-50%,-50%)'
        }
    })
}
