/**
 * CAMARA: modos orbit / fp (primera persona) / tp (tercera persona) / show (vitrina).
 */
import * as THREE from 'three'
import { LIGHT_SCALE } from '../config.js'
import { state } from '../core/state.js'
import { damp, motionScale } from '../core/utils.js'
import { player } from './player.js'
import { quake } from './quake.js'
import { tour, updateTour } from './scrollTour.js'
import { person } from '../three/characters.js'
import { camera, hallLight, lampLight, mainScene, showScene } from '../three/renderer.js'
import { showCameras, showrooms } from '../three/showrooms.js'
import { livingRoom } from '../three/livingRoom.js'
import { world } from '../three/world.js'

const orbit = {
    theta: 0.8,
    r: 16.5,
    h: 10,
    tx: 0,
    ty: 1,
    tz: 0,
    speed: 0.09,
    amp: 0.3,
    sx: 0,
    sy: 0,
}
export const showCam = {
    goal: new THREE.Vector3(),
    tgt: new THREE.Vector3(0, 1, 0),
    cur: new THREE.Vector3(0, 1, 0),
    key: 'pets',
    d: 10,
    sx: 0,
    sy: 0,
    follow: null,
    offY: 0,
    rate: 4,
}
export const fovBoost = {
    v: 0,
    t: 0,
}
const tmpVec2 = new THREE.Vector3()
const tpFollow = new THREE.Vector3()
// Acercamiento de la vista isometrica a un punto (para ver a la mascota donde esta): k va de 0 (normal) a 1 (cerca)
export const tpZoom = { target: null, k: 0, off: new THREE.Vector3(3.4, 1.9, 3.4) }
const TP_FAR = { x: 9, y: 9.2, z: 9 } // desplazamiento normal de la camara respecto al punto que mira
/**
 * Acerca la camara a un punto 3D (o la devuelve a la normalidad con null). instant = sin animacion.
 * yaw = hacia donde mira la mascota: la camara se pone delante de ella, a `dist` metros y un poco mas alta.
 */
export function setTpZoom(point, instant, yaw = Math.PI / 4, dist = 2.3) {
    tpZoom.target = point ? point.clone() : null
    tpZoom.off.set(Math.sin(yaw) * dist, 0.5, Math.cos(yaw) * dist)
    if (instant) {
        tpZoom.k = point ? 1 : 0
        if (point) showCam.cur.copy(point)
    }
}

/**
 * ESCENARIO: las "vitrinas" del kit y del rastreo se montan dentro de la sala (no en un fondo azul aparte).
 * La camara usa la misma logica de vitrina, pero en el espacio de la sala: origin = donde se coloca el grupo,
 * s = su escala, yaw = hacia donde mira la camara y lift = metros extra de altura de los ojos.
 */
export const stage = {
    active: false,
    group: null,
    origin: new THREE.Vector3(),
    yaw: 0,
    s: 1,
    lift: 0,
    liftGoal: 0,
    offset: new THREE.Vector3(), // desfase de la camara al entrar, que se va a cero
}
const stageUp = new THREE.Vector3(0, 1, 0)
const stageTmp = new THREE.Vector3()
const stageFwd = new THREE.Vector3()
const toShowSpace = (world) => world.sub(stage.origin).applyAxisAngle(stageUp, -stage.yaw).multiplyScalar(1 / stage.s)
const toWorld = (local) =>
    local.multiplyScalar(stage.s).applyAxisAngle(stageUp, stage.yaw).add(stage.origin)
/**
 * Monta la vitrina `name` en la sala, en `origin` y con escala `s`. La camara arranca exactamente donde estaba
 * (sin corte) y desde ahi se va acomodando a la vista de la vitrina.
 */
export function enterStage(name, origin, s, lift = 0.12) {
    const group = showrooms[name]
    // pose actual de la camara (en el mundo) y punto al que mira
    const from = camera.position.clone()
    camera.getWorldDirection(stageFwd)
    const dist = Math.hypot(from.x - origin.x, from.z - origin.z)
    const look = from.clone().addScaledVector(stageFwd, dist)
    mainScene.add(group)
    group.position.copy(origin)
    group.scale.setScalar(s)
    stage.group = group
    stage.origin.copy(origin)
    stage.s = s
    stage.yaw = Math.atan2(from.x - origin.x, from.z - origin.z)
    stage.active = true
    showRoom(name)
    showCam.tgt.copy(toShowSpace(look.clone()))
    showCam.d = Math.max(1, dist / s)
    // altura de los ojos: igual a la de la camara anterior y luego baja a `lift`
    const natural = origin.y + s * (showCam.tgt.y + showCam.d * 0.14)
    stage.lift = from.y - natural
    stage.liftGoal = lift
    group.rotation.y = stage.yaw
    // si la camara no apuntaba justo al centro, queda un pequeno desfase lateral: se disuelve poco a poco (sin saltos)
    const predicted = toWorld(stageTmp.set(showCam.tgt.x, showCam.tgt.y + showCam.d * 0.14, showCam.tgt.z + showCam.d))
    stage.offset.set(from.x - predicted.x, 0, from.z - predicted.z)
}
/**
 * CAMARA DE CINE (modo 'cine'): la sala en tercera persona con una camara libre que el paso mueve con
 * cineGo (se acerca suave a un punto y una mirada) o cineSet (salta directo).
 */
export const cine = {
    pos: new THREE.Vector3(),
    look: new THREE.Vector3(),
    goalPos: new THREE.Vector3(),
    goalLook: new THREE.Vector3(),
    rate: 3,
}
/** Empieza donde esta la camara ahora, mirando hacia donde miraba: asi no hay cortes. */
export function cineStart() {
    camera.getWorldDirection(stageFwd)
    cine.pos.copy(camera.position)
    cine.look.copy(camera.position).addScaledVector(stageFwd, 3)
    cine.goalPos.copy(cine.pos)
    cine.goalLook.copy(cine.look)
}
/** La camara se acerca (con suavidad, `rate` mayor = mas rapido) a esta posicion y mirada. */
export function cineGo(pos, look, rate = 3) {
    cine.goalPos.copy(pos)
    cine.goalLook.copy(look)
    cine.rate = rate
}
/** La camara salta directo a esta posicion y mirada. */
export function cineSet(pos, look) {
    cine.pos.copy(pos)
    cine.look.copy(look)
    cine.goalPos.copy(pos)
    cine.goalLook.copy(look)
}
export function updateCamera(dt) {
    // de cerca, al ver a la mascota, la pantalla casi no tiembla
    let t = quake.shakeK * motionScale * (state.mode === 'tp' ? 1 - 0.9 * tpZoom.k : 1)
    if (state.mode === 'fp' && tour.active) {
        updateTour(dt)
    } else if (state.mode === 'fp') {
        let a = 1.55 + (player.moving ? Math.sin(player.bob) * 0.035 : 0)
        camera.position.set(player.pos.x, a, player.pos.z)
        camera.rotation.set(player.pitch, player.yaw, 0)
    } else if (state.mode === 'tp') {
        const follow = tpZoom.target || tpFollow.set(player.pos.x * 0.75, 0.9, player.pos.z * 0.75)
        showCam.cur.lerp(follow, 1 - Math.exp(-(tpZoom.target ? 2.6 : 5) * dt))
        tpZoom.k = damp(tpZoom.k, tpZoom.target ? 1 : 0, 2.2, dt)
        const k = tpZoom.k
        camera.position.set(
            showCam.cur.x + TP_FAR.x + (tpZoom.off.x - TP_FAR.x) * k,
            showCam.cur.y + TP_FAR.y + (tpZoom.off.y - TP_FAR.y) * k,
            showCam.cur.z + TP_FAR.z + (tpZoom.off.z - TP_FAR.z) * k,
        )
        camera.lookAt(showCam.cur)
    } else if (state.mode === 'cine') {
        const k = 1 - Math.exp(-cine.rate * dt)
        cine.pos.lerp(cine.goalPos, k)
        cine.look.lerp(cine.goalLook, k)
        camera.position.copy(cine.pos)
        camera.lookAt(cine.look)
    } else if (state.mode === 'orbit') {
        let a = orbit.theta + Math.sin(state.time * orbit.speed) * orbit.amp
        camera.position.set(orbit.tx + Math.cos(a) * orbit.r, orbit.h, orbit.tz + Math.sin(a) * orbit.r)
        camera.lookAt(orbit.tx, orbit.ty, orbit.tz)
        camera.translateX(-orbit.sx)
        camera.translateY(-orbit.sy)
    } else {
        // vitrina (show) o escenario dentro de la sala (stage): mismo calculo, en el espacio de la vitrina
        const inStage = state.mode === 'stage' && stage.active
        let a = showCam.follow ? showCam.follow.getWorldPosition(tmpVec2) : tmpVec2.fromArray(showCam.goalT)
        if (inStage && showCam.follow) a = toShowSpace(a)
        showCam.tgt.lerp(a, 1 - Math.exp(-4 * dt))
        showCam.d = damp(showCam.d, showCam.goalD, showCam.rate || 4, dt)
        let o = showCam.d
        if (inStage) {
            stage.lift = damp(stage.lift, stage.liftGoal, 2.5, dt)
            camera.position.copy(toWorld(stageTmp.set(showCam.tgt.x, showCam.tgt.y + o * 0.14, showCam.tgt.z + o)))
            camera.position.y += stage.lift
            stage.offset.x = damp(stage.offset.x, 0, 2.5, dt)
            stage.offset.z = damp(stage.offset.z, 0, 2.5, dt)
            camera.position.add(stage.offset)
            camera.lookAt(toWorld(stageTmp.copy(showCam.tgt)))
        } else {
            camera.position.set(showCam.tgt.x, showCam.tgt.y + o * 0.14, showCam.tgt.z + o)
            camera.lookAt(showCam.tgt)
        }
        let s = innerWidth > 820
        showCam.sx = damp(showCam.sx, showCam.follow && s ? o * 0.2 : 0, 4, dt)
        showCam.sy = damp(
            showCam.sy,
            showCam.follow ? (s ? 0 : o * 0.17) : showCam.offY ? showCam.offY * o : 0,
            2.5,
            dt,
        )
        const unit = inStage ? stage.s : 1
        camera.translateX(showCam.sx * unit)
        camera.translateY(-showCam.sy * unit)
        let r = showCameras[showCam.key] || {
            sway: 0.3,
        }
        if (showrooms[showCam.grp]) {
            showrooms[showCam.grp].rotation.y = damp(
                showrooms[showCam.grp].rotation.y,
                (inStage ? stage.yaw : 0) +
                    state.showRot +
                    Math.sin(state.time * 0.6) * r.sway * (showCam.follow ? 0 : 1),
                10,
                dt,
            )
        }
    }
    if (t > 0.001) {
        camera.position.x += (Math.random() - 0.5) * 0.16 * t
        camera.position.y += (Math.random() - 0.5) * 0.12 * t
        camera.position.z += (Math.random() - 0.5) * 0.16 * t
        camera.rotateZ((Math.random() - 0.5) * 0.025 * t)
    }
}
export function setCameraMode(mode) {
    const prev = state.mode
    state.mode = mode
    state.scene = mode === 'show' ? showScene : mainScene
    // al salir del escenario, su vitrina se oculta (queda montada en la sala)
    if (mode !== 'stage') {
        stage.active = false
        if (stage.group) stage.group.visible = false
    }
    let t = mode === 'orbit' || mode === 'tp',
        a = mode === 'fp' || mode === 'stage' || mode === 'cine'
    world.walls.front.visible = !t
    world.walls.right.visible = !t
    world.ceil.visible = a
    world.hallOn = a
    world.hall.visible = a
    world.plug.visible = !a
    hallLight.intensity = a ? 0.45 * LIGHT_SCALE : 0
    person.visible = mode === 'tp'
    // Primera persona = sala exportada de Blender; el resto = casa de cajas
    livingRoom.root.visible = a
    world.root.visible = !a
    lampLight.visible = !a
    // entre la primera persona y el escenario el campo de vision cambia suavemente (lo hace main.js), sin salto
    const inRoom = (m) => m === 'fp' || m === 'stage' || m === 'cine'
    const smoothFov = prev !== mode && inRoom(prev) && inRoom(mode)
    if (!smoothFov) {
        camera.fov = mode === 'cine' ? 50 : mode === 'stage' ? 36 : a ? 68 : mode === 'show' ? 36 : 34
        camera.updateProjectionMatrix()
    }
    if (mode === 'tp') {
        showCam.cur.set(player.pos.x * 0.75, 0.9, player.pos.z * 0.75)
        tpZoom.target = null
        tpZoom.k = 0
    }
}
export function setOrbit(opts) {
    Object.assign(
        orbit,
        {
            theta: 0.8,
            r: 16.5,
            h: 10,
            tx: 0,
            ty: 1,
            tz: 0,
            speed: 0.09,
            amp: 0.3,
            sx: 0,
            sy: 0,
        },
        opts || {},
    )
}
export function showRoom(group, camKey) {
    Object.keys(showrooms).forEach((s) => (showrooms[s].visible = s === group))
    let a = showCameras[camKey || group]
    showCam.key = camKey || group
    showCam.grp = group
    showCam.goalT = a.t
    showCam.goalD = a.d
    showCam.follow = null
    showCam.offY = 0
    showCam.rate = 4
    state.showRot = 0
    let o = showrooms[group]
    ;['dog', 'cat'].forEach((s) => {
        if (o[s] && o[s].userData && o[s].userData.type) {
            o[s].userData.hop = 0
        }
    })
}
export function focusOn(target, distance, rotation) {
    if (!target) {
        let o = showCameras[showCam.key]
        showCam.follow = null
        showCam.goalD = o.d
        state.showRot = 0
        return
    }
    showCam.follow = target
    showCam.goalD = distance || 3.6
    state.showRot = rotation || 0
}
