/**
 * PERSONAJES: instancias de Cacao (dog), Nube (cat) y el usuario (person)
 * mas utilidades para colocarlos, hacerlos caminar y cambiar su estado de animo.
 */
import { petPalettes } from '../config.js'
import { state } from '../core/state.js'
import { angleDiff, damp } from '../core/utils.js'
import { createPerson } from './models/person.js'
import { allPets, createCat, createDog } from './models/pets.js'
import { createFearBubble } from './models/props.js'
import { mainScene } from './renderer.js'
import { KIT_MOUTH, showrooms } from './showrooms.js'

export let dog
export let cat
export let person
export const fearBubbles = []
export const catHideSpots = [
    [-6.2, 0, 0.5],
    [-5.4, 0.65, 3.5],
    [4.3, 0.9, -4.6],
]
export function placePet(pet, x, y, z, rotY, scale) {
    let i = pet.userData
    i.path = null
    i.walking = false
    i.pop = null
    i.ty = null
    i.faceTo = null
    i.sc = scale || 1
    i.base.set(x, y, z)
    pet.position.set(x, y, z)
    pet.rotation.y = rotY || 0
    pet.scale.setScalar(scale || 1)
    pet.scale.y = scale || 1
}
export function popIn(pet) {
    let t = pet.userData
    pet.visible = true
    t.pop = 0
    t.hop = 1
    pet.scale.setScalar(0.001)
}
export function walkPath(pet, path, speed) {
    let o = pet.userData
    o.path = path.map((s) => Object.assign({}, s))
    o.speed = speed || 3.4
    o.walking = true
    o.faceTo = null
}
export function setPetMood(pet, mood) {
    let a = pet.userData
    a.wag = mood.wag != null ? mood.wag : 1
    a.shiver = mood.shiver || 0
    a.eyes.forEach((o) => o.scale.setScalar(mood.eyes || 1))
}
export function createCharacters() {
    dog = createDog(petPalettes.cacao)
    cat = createCat(petPalettes.nube)
    person = createPerson()
    person.visible = false
    mainScene.add(dog, cat, person)
    catHideSpots.forEach((e) => {
        let t = createFearBubble()
        t.position.set(e[0], e[1] + 1.4, e[2])
        t.visible = false
        mainScene.add(t)
        fearBubbles.push(t)
    })
}
export function updateCharacters(dt) {
    if (
        (allPets.forEach((t) => {
            let a = t.userData
            if (a.path && a.path.length) {
                let s = a.path[0]
                a.ty = s.y || 0
                let r = s.x - a.base.x,
                    i = s.z - a.base.z,
                    n = Math.hypot(r, i),
                    d = a.speed * dt
                if (n <= d) {
                    a.base.x = s.x
                    a.base.z = s.z
                    a.path.shift()
                    if (!a.path.length) {
                        a.walking = false
                        a.faceTo = s.ry != null ? s.ry : null
                    }
                } else {
                    a.base.x += (r / n) * d
                    a.base.z += (i / n) * d
                    t.rotation.y += angleDiff(t.rotation.y, Math.atan2(r, i)) * Math.min(1, dt * 10)
                }
            } else {
                if (a.faceTo != null) {
                    t.rotation.y += angleDiff(t.rotation.y, a.faceTo) * Math.min(1, dt * 8)
                }
            }
            if ((a.ty != null && (a.base.y = damp(a.base.y, a.ty, 7, dt)), a.pop != null)) {
                a.pop = Math.min(1, a.pop + dt * 2.4)
                let s = a.pop - 1,
                    r = 1 + 2.70158 * s * s * s + 1.70158 * s * s,
                    i = (a.sc || 1) * Math.max(0.001, r)
                t.scale.set(i, i, i)
                if (a.pop >= 1) {
                    a.pop = null
                }
            }
            if (a.type === 'dog' && a.tail) {
                a.tail.rotation.z = Math.sin(state.time * 9 + a.ph) * 0.5 * a.wag
            } else if (a.tail) {
                a.tail.rotation.y = Math.sin(state.time * 3 + a.ph) * 0.35 * a.wag
            }
            if (a.head && !(a.shiver > 0.3)) {
                a.head.rotation.y = Math.sin(state.time * 0.8 + a.ph) * 0.25
                a.head.rotation.z = Math.sin(state.time * 1.3 + a.ph) * 0.05
            } else if (a.head) {
                a.head.rotation.y = Math.sin(state.time * 2 + a.ph) * 0.12
                a.head.rotation.z = 0
            }
            t.position.x =
                a.base.x + (a.shiver ? Math.sin(state.time * 55 + a.ph) * 0.012 * a.shiver * t.scale.x : 0)
            t.position.z = a.base.z
            // al caminar rebota un poco; al correr (a.run) rebota mas y mas rapido, como un galope
            let o = a.walking
                ? Math.abs(Math.sin(state.time * (a.run ? 22 : 13) + a.ph)) * (a.run ? 0.17 : 0.07) * t.scale.x
                : 0
            if (a.hop > 0) {
                a.hop = Math.max(0, a.hop - dt * 2.2)
                t.position.y = a.base.y + o + Math.sin((1 - a.hop) * Math.PI) * 0.35 * t.scale.x
            } else {
                t.position.y = a.base.y + o
            }
        }),
        showrooms.fin && showrooms.fin.visible)
    ) {
        let t = showrooms.fin.motes.geometry.attributes.position
        for (let a = 0; a < t.count; a++) {
            let o = t.getY(a) + dt * (0.28 + (a % 5) * 0.09)
            if (o > 6) {
                o = -0.2
            }
            t.setY(a, o)
            t.setX(a, t.getX(a) + Math.sin(state.time * 0.8 + a) * 0.002)
        }
        t.needsUpdate = true
    }
    if (showrooms.kit && showrooms.kit.visible) {
        const kit = showrooms.kit
        let squash = 0 // la mochila se "infla" un poco cuando sale o entra un objeto
        kit.items.forEach((item) => {
            const a = item.userData
            if (a.stage === 'in' || a.stage === 'stored') {
                item.visible = false
                return
            }
            if (a.stage === 'emerging' || a.stage === 'storing') {
                const emerging = a.stage === 'emerging'
                a.t += dt / (emerging ? 0.9 : 0.6)
                if (a.t < 0) {
                    item.visible = false
                    return
                }
                item.visible = true
                const k = Math.min(1, a.t)
                if (emerging) {
                    const e = easeOutBack(k)
                    item.position.lerpVectors(KIT_MOUTH, a.base, e)
                    item.position.y += Math.sin(k * Math.PI) * 0.9
                    item.scale.setScalar(Math.max(0.001, e))
                } else {
                    const e = k * k * (3 - 2 * k)
                    item.position.lerpVectors(a.from, KIT_MOUTH, e)
                    item.position.y += Math.sin(k * Math.PI) * 0.5
                    item.scale.setScalar(Math.max(0.001, 1 - e))
                }
                item.rotation.y += dt * 3
                squash = Math.max(squash, Math.sin(Math.min(1, k * 2) * Math.PI))
                if (k >= 1) {
                    a.stage = emerging ? 'out' : 'stored'
                    if (!emerging) item.visible = false
                }
                return
            }
            // out: flota suavemente
            item.position.y = a.base.y + Math.sin(state.time * 1.6 + a.ph) * 0.08
            item.rotation.y += dt * 0.6
            const o = damp(
                item.scale.x,
                a.sel ? 1.35 : item.children.length && a.base.y === 2.6 ? 1.15 : 1,
                8,
                dt,
            )
            item.scale.setScalar(o)
        })
        // Entrada: la mochila cae, rebota y gira hasta quedar de frente
        kit.intro = Math.min(1, kit.intro + dt / 1.5)
        const k = kit.intro
        const fall = Math.min(1, k / 0.45)
        const bounce = Math.min(1, Math.max(0, (k - 0.45) / 0.55))
        kit.bag.position.y =
            k < 0.45 ? 2.6 * (1 - fall * fall) : 0.35 * Math.sin(bounce * Math.PI) * (1 - bounce)
        kit.bag.rotation.y = (1 - (1 - (1 - k) ** 3)) * Math.PI * 2
        if (k >= 0.45 && bounce < 0.35) squash = Math.max(squash, 1.6 * Math.sin((bounce / 0.35) * Math.PI))
        // Tapa: se levanta y se inclina hacia atras al abrir
        kit.open = damp(kit.open, kit.lidTarget, 7, dt)
        kit.lid.position.set(0, 1.42 + 0.5 * kit.open, -0.3 * kit.open)
        kit.lid.rotation.x = -1.0 * kit.open
        kit.handle.position.set(0, 1.78 + 0.5 * kit.open, -0.3 * kit.open)
        kit.handle.rotation.x = -1.0 * kit.open
        kit.bag.scale.set(1 + 0.05 * squash, 1 - 0.06 * squash, 1 + 0.05 * squash)
    }
}

const easeOutBack = (k) => 1 + 2.70158 * (k - 1) ** 3 + 1.70158 * (k - 1) ** 2
