/**
 * NAVEGACION entre pasos: registro `steps`, goTo(), transiciones y reinicio.
 * Cada paso vive en su archivo (intro, before, during, sizes, after, ending).
 */
import { audio } from '../audio/audio.js'
import { session, state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { fovBoost } from '../systems/camera.js'
import { player } from '../systems/player.js'
import { quake, stopQuake } from '../systems/quake.js'
import { resetBooks } from '../systems/quakeEffects.js'
import { cat, dog } from '../three/characters.js'
import { updateBanner } from '../ui/banner.js'
import { resetScreen } from '../ui/panels.js'
import { setStage } from '../ui/seismo.js'

function cleanupStep() {
    if (state.curExit) {
        state.curExit()
        state.curExit = null
    }
    if (state.stepData.io) {
        state.stepData.io.disconnect()
        state.stepData.io = null
    }
    state.curTick = null
    state.onQuakePhase = function () {}
    state.stepData = {}
}
let fading = false
// Duracion (ms) del fundido a negro al llegar a cada paso; los demas usan 800
const FADE_MS = { quakeIntro: 1500, sizeIntro: 1200 }
export function transitionTo(name, params, duration) {
    if (fading) return
    fading = true
    const ms = duration || FADE_MS[name] || 800
    let a = qs('#fade')
    a.style.transitionDuration = ms + 'ms'
    a.classList.add('on')
    setTimeout(() => {
        goTo(name, params)
        requestAnimationFrame(() =>
            setTimeout(() => {
                a.classList.remove('on')
                setTimeout(() => {
                    a.style.transitionDuration = ''
                    fading = false
                }, ms)
            }, 250),
        )
    }, ms)
}
/**
 * Transicion de "Iniciar simulacion": ondas de colores salen del boton, la camara se abre en un "zoom" y un iris
 * azul cubre la pantalla; detras arranca la introduccion y el iris se cierra hacia el centro para revelarla.
 */
let startWipeRunning = false
export function playStartWipe(originEl) {
    if (startWipeRunning) return
    startWipeRunning = true
    const wipe = qs('#wipe')
    const box = originEl.getBoundingClientRect()
    wipe.style.setProperty('--x', box.left + box.width / 2 + 'px')
    wipe.style.setProperty('--y', box.top + box.height / 2 + 'px')
    wipe.className = 'on'
    wipe.offsetWidth
    wipe.classList.add('go')
    audio.whoosh()
    fovBoost.t = 0.8
    setTimeout(() => {
        goTo('start')
        fovBoost.t = 0
        wipe.classList.remove('go')
        wipe.classList.add('open')
    }, 1500)
    setTimeout(() => {
        wipe.className = ''
        startWipeRunning = false
    }, 2800)
}
/** Resuelve el destino de "Regresar" / "Siguiente": un nombre de paso o una funcion que lo calcula. */
function resolveTarget(target, params) {
    return typeof target === 'function' ? target(params) : target
}
/** Botones Regresar / Siguiente de la linea de tiempo: se actualizan en cada paso. */
function updateStepNav(name, step, params) {
    const back = qs('#navBack')
    const next = qs('#navNext')
    back.hidden = !step.prev
    next.hidden = !step.next
    // en el inicio no se muestra la navegacion
    qs('#navbar').classList.toggle('nav-off', name === 'home')
    state.navTo = {
        back: step.prev ? () => transitionTo(resolveTarget(step.prev, params)) : null,
        next: step.next
            ? () => {
                  const to = resolveTarget(step.next, params)
                  if (typeof to === 'string') transitionTo(to)
              }
            : null,
    }
}
export function navGo(dir) {
    const go = state.navTo && state.navTo[dir]
    if (go) {
        audio.blip()
        go()
    }
}
export function goTo(name, params) {
    cleanupStep()
    resetScreen()
    player.locked = false
    state.bgOverride = null
    state.hideBanner = false
    let a = steps[name]
    if (!a) return
    state.cur = name
    state.lastBanner = '#'
    qs('#hud').hidden = name === 'home' && false
    // El sismo sigue durante toda la etapa 2 (tambien en los tamanos, mas suave); solo se reinicia en quakeIntro
    let o = a.stage === 2 && name !== 'quakeIntro'
    if (!o && quake.active) {
        stopQuake()
    }
    // Musica: tension suave desde la tarjeta que abre la etapa 2 hasta las experiencias; otra distinta en los tamanos
    const mood =
        a.stage === 2
            ? name.startsWith('size')
                ? 'sizes'
                : o || name === 'quakeIntro'
                  ? 'suspense'
                  : 'calm'
            : a.stage === 3
              ? 'hope'
              : 'calm'
    audio.setMood(mood)
    setStage(a.stage, a.w || 0)
    updateStepNav(name, a, params || {})
    a.enter(params || {})
    updateBanner()
}
function restartExperience() {
    stopQuake()
    resetBooks()
    session.done.clear()
    session.sizes.clear()
    session.greeted = false
    dog.visible = cat.visible = true
    goTo('home')
}
let wipeRunning = false
export function playRestartWipe(originEl) {
    if (wipeRunning) return
    wipeRunning = true
    let t = qs('#wipe'),
        a = originEl.getBoundingClientRect()
    t.style.setProperty('--x', a.left + a.width / 2 + 'px')
    t.style.setProperty('--y', a.top + a.height / 2 + 'px')
    t.className = 'on'
    t.offsetWidth
    t.classList.add('go')
    audio.whoosh()
    fovBoost.t = 1
    setTimeout(() => t.classList.add('hold'), 1e3)
    setTimeout(() => {
        restartExperience()
        fovBoost.t = 0
    }, 1750)
    setTimeout(() => {
        t.classList.remove('go', 'hold')
        t.classList.add('open')
    }, 2600)
    setTimeout(() => {
        t.className = ''
        wipeRunning = false
    }, 3900)
}
export const steps = {}
