/**
 * PASOS de la etapa DURANTE: aviso, hub de tres experiencias, misiones con tiempo
 * y sus pantallas de cierre.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { MISSION_SECONDS, QUAKE } from '../config.js'
import { session, state } from '../core/state.js'
import { isTouch, qs, qsa } from '../core/utils.js'
import { content } from '../data/content.js'
import { petFaces } from '../data/icons.js'
import { goTo, steps, transitionTo } from './navigation.js'
import { setCameraMode, setOrbit, setTpZoom } from '../systems/camera.js'
import { catChase } from '../systems/catChase.js'
import { setBeacon, setInteract } from '../systems/interaction.js'
import { player, resetPlayer } from '../systems/player.js'
import { quake, startQuake } from '../systems/quake.js'
import { dropBooks, resetBooks } from '../systems/quakeEffects.js'
import { cat, catHideSpots, dog, fearBubbles, person, placePet, setPetMood } from '../three/characters.js'
import { mainScene } from '../three/renderer.js'
import { addHotspot } from '../ui/hotspots.js'
import { setObjective, showMoveHint, showTimer, updateTimer } from '../ui/hud.js'
import { showDynamic, showPanel } from '../ui/panels.js'

// Lugares donde puede estar escondido Cacao en la primera experiencia (x, z en metros; r = alcance para revisar)
// dog = donde se ve a Cacao al encontrarlo (debajo de la mesa, al lado de la cama y del librero)
const SEARCH_SPOTS = [
    { x: 3.2, z: 1.8, r: 2.1, dog: { x: 3.2, z: 1.8, ry: Math.PI / 2 } }, // la mesa
    { x: -3.9, z: 3.6, r: 1.8, dog: { x: -3.95, z: 3.6, ry: Math.PI } }, // la cama
    { x: -0.8, z: -3.7, r: 1.8, dog: { x: -0.8, z: -4.2, ry: 0 } }, // el librero
]

/**
 * Resultado de una experiencia sin cortes: la camara se acerca a la mascota en la misma casa,
 * se ve donde esta y, un momento despues, aparece la tarjeta con la explicacion.
 * instant = ya con la camara cerca (al llegar con "Siguiente" desde otro paso).
 */
// Desde donde se ve a la mascota al encontrarla: hacia donde mira (la camara queda delante de ella)
const REVEAL_YAW = { hide: Math.PI / 2, still: 0, cat: Math.PI / 2 }
function revealPet(k, instant) {
    const text = content.mission[k]
    session.done.add(k)
    player.locked = true
    person.visible = false
    state.hideBanner = true
    qs('#hotspots').style.visibility = 'hidden'
    setObjective(null)
    setBeacon(null)
    setInteract(null)
    showTimer(false)
    fearBubbles.forEach((b) => (b.visible = false))
    const pet = k === 'cat' ? cat : dog
    pet.visible = true
    const spot = pet.userData.base
    // la camara se pone de frente a la mascota (que mira hacia ella) y el temblor baja para poder verla bien
    const yaw = REVEAL_YAW[k]
    pet.userData.faceTo = yaw
    if (instant) pet.rotation.y = yaw
    setTpZoom(new THREE.Vector3(spot.x, spot.y + 0.45, spot.z), instant, yaw, 2.3)
    quake.shakeTarget = 0.15 // solo baja el temblor de la camara; la luz se queda igual
    const leave = state.curExit
    state.curExit = () => {
        if (leave) leave()
        quake.shakeTarget = 1
    }
    if (k === 'hide') {
        setPetMood(dog, { wag: 0, shiver: 0.9, eyes: 1.35 })
        audio.whimper()
    } else if (k === 'still') {
        setPetMood(dog, { wag: 0, shiver: 0.4, eyes: 1.4 })
        audio.whimper()
    } else {
        setPetMood(cat, { wag: 0.4, shiver: 0.3, eyes: 1.4 })
        audio.meow()
    }
    setTimeout(
        () => {
            if (!state.stepData.reveal) return
            showPanel({
                title: text.title,
                text: text.text,
                actions: [{ label: 'Regresar', fn: () => transitionTo('hub', null, 900) }],
            })
        },
        instant ? 300 : 1900,
    )
    state.stepData.reveal = true
}

steps.quakeIntro = {
    stage: 2,
    w: 0.04,
    prev: 'antesEnd',
    next: 'hub',
    enter() {
        setCameraMode('orbit')
        setOrbit({
            r: 18,
            h: 11,
        })
        resetBooks()
        resetPlayer(0, 3.5, 0)
        session.done.clear()
        // Empieza a temblar el fondo (la casa), pero la tarjeta de texto se queda quieta y aparece con fundido
        audio.init()
        startQuake()
        state.bgOverride = 'night' // el fondo detras de la habitacion se oscurece casi a negro azulado
        const intro = content.quakeIntro
        const words = intro.text
            .split(' ')
            .map((w, i) => '<span style="--i:' + i + '">' + w + '</span>')
            .join(' ')
        const panel = showPanel({
            cls: 'center quakecard',
            html:
                '<svg class="qline" viewBox="0 0 400 40" preserveAspectRatio="none" aria-hidden="true"><path pathLength="1" d="M0 20H120l8-4 8 8 8-16 8 28 8-34 8 30 8-22 8 14 8-6 8 4H400"/></svg>' +
                '<span class="qkick">' +
                intro.kick +
                '</span><h2 class="qtitle">' +
                intro.title +
                '</h2><p class="qtext">' +
                words +
                '</p>',
            actions: [
                {
                    label: intro.cta,
                    cls: 'danger',
                    fn: () => {
                        // la tarjeta se desvanece mientras la escena se funde; luego aparecen las experiencias despacio
                        panel.classList.add('leaving')
                        transitionTo('hub', null, 1100)
                    },
                },
            ],
        })
    },
}
steps.hub = {
    stage: 2,
    w: 0.3,
    prev: 'quakeIntro',
    next: 'sizeIntro',
    enter() {
        setCameraMode('orbit')
        setOrbit({
            r: 19,
            h: 12,
            sy: innerWidth > 720 ? 2.6 : 3.6,
            amp: 0.12,
        })
        quake.shakeTarget = 1 // el temblor de las experiencias (en los tamanos es mas suave)
        quake.target = QUAKE.intensity
        let hubText = content.hub
        placePet(dog, -4.4, 0.75, -4.05, 0.1, 0.62)
        setPetMood(dog, {
            wag: 0,
            shiver: 0.6,
            eyes: 1.25,
        })
        // Solo en esta pantalla la habitacion se ve sin las mascotas; al salir vuelven a estar disponibles
        dog.visible = false
        cat.visible = false
        state.curExit = () => {
            dog.visible = true
            cat.visible = true
        }
        placePet(cat, -3.5, 0.75, -4.05, -0.1, 0.6)
        setPetMood(cat, {
            wag: 0,
            shiver: 0.6,
            eyes: 1.25,
        })
        if (!quake.active) {
            startQuake()
        }
        let t = showDynamic(
            '<div id="hub" class="active"><div class="wrap"><div class="hhead card"><h2>' +
                hubText.title +
                '</h2><p class="sub">' +
                hubText.sub +
                '</p><p class="limit">' +
                hubText.limit.replace('{n}', MISSION_SECONDS) +
                '</p></div><div class="cards">' +
                hubText.cards
                    .map(
                        (a, i) =>
                            '<div class="exp card" style="--d:' +
                            (0.75 + i * 0.35).toFixed(2) +
                            's">' +
                            petFaces[a.pet] +
                            '<div class="txt"><h3>' +
                            a.t +
                            '</h3><p>' +
                            a.d +
                            '</p></div><button class="btn" data-k="' +
                            a.k +
                            '">' +
                            hubText.cta +
                            '</button>' +
                            (session.done.has(a.k) ? '<span class="badge">' + hubText.done + '</span>' : '') +
                            '</div>',
                    )
                    .join('') +
                '</div><div class="foot" style="--d:1.8s"><button class="btn" id="hubNext" ' +
                (session.done.size < 3 ? 'hidden' : '') +
                '>' +
                hubText.next +
                '</button></div></div></div>',
        )
        qsa('.exp .btn', t).forEach((a) =>
            a.addEventListener('click', () => {
                audio.blip()
                // la escena se desvanece y aparece la habitacion, sin corte
                transitionTo('mission', { k: a.dataset.k }, 1000)
            }),
        )
        qs('#hubNext', t).addEventListener('click', () => {
            audio.blip()
            goTo('sizeIntro')
        })
    },
}
steps.mission = {
    stage: 2,
    w: 0.5,
    prev: 'hub',
    next: (p) => 'close_' + p.k, // salta al resultado de esta experiencia
    enter(e) {
        let t = e.k,
            a = content.mission[t],
            o = MISSION_SECONDS
        setCameraMode('tp')
        resetPlayer(t === 'cat' ? 0 : -1, 3.2, 0)
        person.scale.y = 1
        showMoveHint()
        if (isTouch) {
            qs('#stick').hidden = false
        }
        if (e.retry) {
            resetBooks()
            dropBooks(6)
        }
        let s = 0,
            r = false,
            i = o,
            lastSecond = o,
            n = false,
            d = null,
            u = (dogAt) => {
                n = true
                if (dogAt) {
                    // Cacao aparece en el lugar donde estaba escondido
                    placePet(dog, dogAt.x, 0, dogAt.z, dogAt.ry, 0.62)
                    dog.scale.y = 0.5
                }
                revealPet(t, false)
            },
            h = () => {
                n = true
                player.locked = true
                setInteract(null)
                setBeacon(null)
                setObjective(null)
                showTimer(false)
                audio.no()
                audio.whimper()
                // todo se funde a negro despacio y solo queda la tarjeta, que aparece con un desvanecimiento lento
                qs('#blackout').classList.add('on')
                let p = content.mission.fail
                showPanel({
                    title: p.t,
                    text: p.s,
                    cls: 'center fail',
                    actions: [
                        {
                            label: p.cta,
                            fn: () => {
                                // todo se va a negro del todo y entonces empieza de nuevo la experiencia
                                qs('#panel').classList.add('leaving')
                                qs('#blackout').classList.add('full')
                                setTimeout(
                                    () =>
                                        state.cur === 'mission' &&
                                        goTo('mission', {
                                            k: t,
                                            retry: true,
                                        }),
                                    1000,
                                )
                            },
                        },
                    ],
                })
            }
        showTimer(true)
        updateTimer(i, o)
        if (t === 'hide') {
            // Cacao esta escondido en uno de tres lugares marcados en la casa; hay que ir a revisarlos
            cat.visible = false
            dog.visible = false
            const hidingIn = Math.floor(Math.random() * SEARCH_SPOTS.length)
            const markers = SEARCH_SPOTS.map((spot, k) => {
                const marker = new THREE.Group()
                const ring = new THREE.Mesh(
                    new THREE.RingGeometry(0.62, 0.78, 40),
                    new THREE.MeshBasicMaterial({
                        color: '#ffc24d',
                        transparent: true,
                        opacity: 0.9,
                        side: THREE.DoubleSide,
                    }),
                )
                ring.rotation.x = -Math.PI / 2
                ring.position.y = 0.04
                const cone = new THREE.Mesh(
                    new THREE.ConeGeometry(0.2, 0.46, 4),
                    new THREE.MeshBasicMaterial({ color: '#ffc24d' }),
                )
                cone.rotation.x = Math.PI
                cone.position.y = 1.5
                marker.add(ring, cone)
                marker.position.set(spot.x, 0, spot.z)
                mainScene.add(marker)
                const label = addHotspot({
                    cls: 'pill',
                    label: a.spots[k],
                    anchor: cone,
                })
                label.classList.add('search')
                return { marker, ring, cone, label, spot, k, checked: false }
            })
            state.curExit = () => markers.forEach((m) => mainScene.remove(m.marker))
            const refreshTargets = () =>
                setInteract(
                    markers
                        .filter((m) => !m.checked)
                        .map((m) => ({
                            x: m.spot.x,
                            z: m.spot.z,
                            r: m.spot.r,
                            label: a.open + ' ' + a.spots[m.k].toLowerCase(),
                            fn: () => {
                                if (m.k === hidingIn) {
                                    markers.forEach((other) => (other.marker.visible = false))
                                    return u(m.spot.dog)
                                }
                                // lugar vacio: se marca como revisado y se avisa
                                m.checked = true
                                m.ring.material.color.set('#9aa8c4')
                                m.cone.visible = false
                                m.label.firstChild.textContent = '✓ ' + a.spots[m.k] + ' · vacío'
                                m.label.classList.add('checked')
                                audio.no()
                                setObjective(a.empty.t, a.empty.s)
                                setTimeout(() => state.cur === 'mission' && setObjective(null), 2200)
                                refreshTargets()
                            },
                        })),
                )
            refreshTargets()
            d = (p) => {
                s += p
                if (s > 4 && !r) {
                    r = true
                    audio.whimper()
                }
                markers.forEach((m) => {
                    m.cone.position.y = 1.5 + Math.sin(state.time * 3 + m.k) * 0.15
                    m.ring.scale.setScalar(m.checked ? 1 : 1 + Math.sin(state.time * 3 + m.k) * 0.12)
                })
            }
        } else if (t === 'still') {
            cat.visible = false
            dog.visible = true
            placePet(dog, -4.4, 0.75, -4.05, 0.1, 0.62)
            setPetMood(dog, {
                wag: 0,
                shiver: 0.35,
                eyes: 1.35,
            })
            setBeacon(-4.4, -4.05, 2.1)
            setInteract({
                x: -4.4,
                z: -4.05,
                r: 2.6,
                label: a.open,
                fn: u,
            })
        } else {
            dog.visible = false
            cat.visible = true
            catChase.reset()
            setPetMood(cat, {
                wag: 1,
                shiver: 0.5,
                eyes: 1.4,
            })
            d = (p) => {
                catChase.update(p)
                if (catChase.cornered && !catChase.dash) {
                    setInteract({
                        x: cat.userData.base.x,
                        z: cat.userData.base.z,
                        r: 2.3,
                        label: a.open,
                        fn: u,
                    })
                } else {
                    setInteract(null)
                }
            }
        }
        state.curTick = (p) => {
            if (!n) {
                if (d) {
                    d(p)
                }
                if (!n) {
                    i -= p
                    updateTimer(i, o)
                    // en los ultimos 5 segundos suena un tic muy leve cada segundo
                    const whole = Math.ceil(i)
                    if (whole !== lastSecond && whole >= 1 && whole <= 5) audio.tick()
                    lastSecond = whole
                    if (i <= 0) {
                        h()
                    }
                }
            }
        }
    },
}
;['hide', 'still', 'cat'].forEach((e) => {
    steps['close_' + e] = {
        stage: 2,
        w: 0.6,
        prev: 'hub',
        next: () => (session.done.size >= 3 ? 'sizeIntro' : 'hub'),
        // Llegar aqui con "Siguiente" muestra el mismo resultado, ya con la camara cerca de la mascota
        enter() {
            setCameraMode('tp')
            resetPlayer(-1, 3.2, 0)
            if (e === 'hide') {
                const spot = SEARCH_SPOTS[0].dog
                cat.visible = false
                placePet(dog, spot.x, 0, spot.z, spot.ry, 0.62)
                dog.scale.y = 0.5
            } else if (e === 'still') {
                cat.visible = false
                placePet(dog, -4.4, 0.75, -4.05, 0.1, 0.62)
            } else {
                dog.visible = false
                const spot = catHideSpots[0]
                placePet(cat, spot[0], spot[1], spot[2], -Math.PI / 2, 0.6)
            }
            revealPet(e, true)
        },
    }
})
