/**
 * MODELOS 3D de las mascotas: perro (createDog) y gata (createCat).
 * Cada uno guarda en userData lo necesario para animarlos (cola, cabeza, anclas).
 */
import * as THREE from 'three'
import { anchor, cylinder, ellipsoid, mesh, place, roundedBox } from '../helpers.js'

export const allPets = []
export function createDog(palette) {
    let t = new THREE.Group(),
        a = t.userData
    a.type = 'dog'
    a.base = new THREE.Vector3()
    a.wag = 1
    a.shiver = 0
    a.hop = 0
    a.ph = Math.random() * 6
    t.add(place(ellipsoid(0.42, palette.fur, 0.9, 1.15, 0.95), 0, 0.5, -0.05))
    t.add(place(ellipsoid(0.3, palette.light, 0.95, 1.1, 0.8), 0, 0.6, 0.14))
    ;[-1, 1].forEach((d) => {
        t.add(place(ellipsoid(0.27, palette.fur, 1, 1, 1.05), d * 0.27, 0.27, -0.17))
        t.add(place(cylinder(0.085, 0.085, 0.55, palette.fur, 12), d * 0.15, 0.3, 0.24))
        t.add(place(ellipsoid(0.11, palette.light, 1, 0.7, 1.3), d * 0.15, 0.06, 0.3))
    })
    let o = new THREE.Group()
    o.position.set(0, 1.02, 0.12)
    t.add(o)
    a.head = o
    o.add(ellipsoid(0.3, palette.fur))
    o.add(place(ellipsoid(0.15, palette.light, 1, 0.8, 1.25), 0, -0.08, 0.27))
    o.add(place(ellipsoid(0.055, palette.nose, 1.2, 0.85, 1), 0, -0.02, 0.42))
    o.add(place(ellipsoid(0.05, '#ff8f9e', 0.8, 0.3, 1), 0, -0.15, 0.36))
    a.eyes = []
    ;[-1, 1].forEach((d) => {
        let u = place(ellipsoid(0.05, '#1c2233'), d * 0.11, 0.07, 0.26)
        u.add(place(ellipsoid(0.016, '#ffffff'), 0.015, 0.02, 0.04))
        o.add(u)
        a.eyes.push(u)
        let h = place(ellipsoid(1, palette.ear, 0.09, 0.2, 0.14), d * 0.25, 0.06, -0.02)
        h.rotation.z = -d * 0.35
        o.add(h)
    })
    let s = place(mesh(new THREE.TorusGeometry(0.2, 0.035, 10, 24), '#ff7a66'), 0, 0.86, 0.14)
    s.rotation.x = Math.PI / 2
    t.add(s)
    let r = place(cylinder(0.06, 0.06, 0.02, '#ffc24d', 16), 0, 0.74, 0.36)
    r.rotation.x = Math.PI / 2
    t.add(r)
    t.add(place(roundedBox(0.12, 0.09, 0.06, 0.02, '#4a8bdd'), 0.21, 0.85, 0.06))
    let i = new THREE.Group()
    i.position.set(0, 0.14, -0.38)
    let n = cylinder(0.045, 0.06, 0.5, palette.fur, 10)
    n.position.set(0, 0.2, -0.1)
    n.rotation.x = -0.5
    i.add(n)
    t.add(i)
    a.tail = i
    a.anchors = {
        neck: anchor(t, 0, 0.86, 0.3),
        back: anchor(t, 0, 0.95, -0.3),
        paws: anchor(t, 0, 0.12, 0.42),
        rear: anchor(t, 0, 0.35, -0.55),
        head: anchor(t, 0, 1.55, 0.1),
        tag: anchor(t, 0, 0.74, 0.42),
        gps: anchor(t, 0.24, 0.86, 0.08),
        chip: anchor(t, 0, 1, -0.15),
    }
    allPets.push(t)
    return t
}
export function createCat(palette) {
    let t = new THREE.Group(),
        a = t.userData
    a.type = 'cat'
    a.base = new THREE.Vector3()
    a.wag = 1
    a.shiver = 0
    a.hop = 0
    a.ph = Math.random() * 6
    let o = {
        emissive: palette.fur,
        emissiveIntensity: 0.12,
    }
    t.add(place(ellipsoid(0.3, palette.fur, 0.95, 1.15, 0.95, o), 0, 0.38, -0.03))
    t.add(place(ellipsoid(0.22, palette.light, 0.9, 1, 0.8), 0, 0.4, 0.14))
    ;[-1, 1].forEach((n) => {
        t.add(place(ellipsoid(0.2, palette.fur, 1, 1, 1.05, o), n * 0.2, 0.2, -0.16))
        t.add(place(cylinder(0.055, 0.055, 0.36, palette.fur, 10), n * 0.11, 0.2, 0.2))
        t.add(place(ellipsoid(0.075, palette.light, 1, 0.7, 1.3), n * 0.11, 0.05, 0.25))
    })
    let s = new THREE.Group()
    s.position.set(0, 0.86, 0.1)
    t.add(s)
    a.head = s
    s.add(ellipsoid(0.25, palette.fur, 1.1, 0.95, 1, o))
    s.add(place(ellipsoid(0.09, palette.light, 1.2, 0.8, 1), 0, -0.07, 0.2))
    s.add(place(ellipsoid(0.03, '#ff9aa8'), 0, -0.02, 0.28))
    a.eyes = []
    ;[-1, 1].forEach((n) => {
        let d = place(mesh(new THREE.ConeGeometry(0.1, 0.2, 4), palette.fur), n * 0.15, 0.22, 0)
        d.rotation.z = -n * 0.25
        s.add(d)
        let u = place(mesh(new THREE.ConeGeometry(0.055, 0.13, 4), '#ffb3a6'), n * 0.15, 0.21, 0.03)
        u.rotation.z = -n * 0.25
        s.add(u)
        let h = place(ellipsoid(0.055, '#2f8f6d'), n * 0.1, 0.05, 0.2)
        h.add(place(ellipsoid(0.026, '#10151f', 0.6, 1.3, 0.6), 0, 0, 0.04))
        s.add(h)
        a.eyes.push(h)
    })
    // Collar de seguridad con placa y localizador (se ven en la estacion de rastreo)
    const collar = place(mesh(new THREE.TorusGeometry(0.23, 0.03, 10, 28), '#ff7a66'), 0, 0.68, 0.1)
    collar.rotation.x = Math.PI / 2
    t.add(collar)
    const tag = place(cylinder(0.05, 0.05, 0.015, '#ffc24d', 16), 0, 0.61, 0.33)
    tag.rotation.x = Math.PI / 2
    t.add(tag)
    t.add(place(roundedBox(0.09, 0.07, 0.05, 0.015, '#4a8bdd'), 0.23, 0.68, 0.1))
    let r = new THREE.Group(),
        i = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0, 0.16, -0.28),
            new THREE.Vector3(0, 0.1, -0.55),
            new THREE.Vector3(0, 0.28, -0.72),
            new THREE.Vector3(0, 0.55, -0.62),
            new THREE.Vector3(0, 0.72, -0.45),
        ])
    r.add(mesh(new THREE.TubeGeometry(i, 20, 0.05, 8, false), palette.fur))
    t.add(r)
    a.tail = r
    a.anchors = {
        neck: anchor(t, 0, 0.66, 0.22),
        back: anchor(t, 0, 0.62, -0.25),
        paws: anchor(t, 0, 0.1, 0.3),
        rear: anchor(t, 0, 0.35, -0.45),
        head: anchor(t, 0, 1.22, 0.1),
        tag: anchor(t, 0, 0.62, 0.36),
        gps: anchor(t, 0.26, 0.68, 0.1),
        chip: anchor(t, 0, 0.74, -0.14),
    }
    allPets.push(t)
    return t
}
