/**
 * ESCENA DEL SOFA: el lugar de la sala donde termina el "Antes". Cacao y Nube estan en el sofa y el
 * personaje se sienta en medio de los dos. Medidas en metros (la sala va de x -2 a 3.4, z -2.9 a 2.9).
 */
import * as THREE from 'three'
import { livingRoom } from '../three/livingRoom.js'
import { person } from '../three/characters.js'

export const DOG_SCALE = 0.42
export const CAT_SCALE = 0.4
export const PERSON_SCALE = 0.8 // el personaje se ve un poco mas pequeno en la sala
export const DOG_X = 1.05 // Cacao a un lado del sofa...
export const CAT_X = 1.95 // ...y Nube al otro; en medio queda el personaje
export const SOFA_Z = 2.3
export const SEAT_X = 1.5
export const SEAT_Z = 2.2 // donde se sienta el personaje: sobre el asiento, algo adelantado para no tocar el respaldo
export const SOFA_FRONT = { x: SEAT_X, z: 1.6 } // frente al sofa, antes de darse la vuelta y sentarse

let seatHeight = null
/** Altura real del asiento del sofa (se mide con un rayo hacia abajo), para que nadie quede flotando. */
export function seatY() {
    if (seatHeight != null) return seatHeight
    livingRoom.root.updateMatrixWorld(true)
    const ray = new THREE.Raycaster(new THREE.Vector3(SEAT_X, 2, SOFA_Z), new THREE.Vector3(0, -1, 0))
    const hit = ray.intersectObject(livingRoom.root, true)[0]
    if (!hit) return 0.45 // la sala todavia no esta cargada: se mide la proxima vez
    seatHeight = hit.point.y > 0.25 && hit.point.y < 0.7 ? hit.point.y : 0.45
    return seatHeight
}

/**
 * Altura (y del personaje) para que quede sentado: los muslos descansan horizontales sobre el asiento
 * (el radio del muslo es 0.09) y la cadera esta a 0.55 de sus pies.
 */
export const seatedY = () => seatY() + 0.05 * PERSON_SCALE - 0.55 * PERSON_SCALE

/** Postura sentado (t = 0 de pie, 1 sentado): muslos al frente sobre el asiento y pantorrillas colgando. */
export function sitPose(t) {
    const limbs = person.userData
    limbs.legL.rotation.x = limbs.legR.rotation.x = -1.5 * t
    limbs.kneeL.rotation.x = limbs.kneeR.rotation.x = 1.5 * t
    limbs.armL.rotation.x = limbs.armR.rotation.x = -0.6 * t
}

/** Deja al personaje de pie y sin postura (al salir de la escena). */
export function resetPerson() {
    const limbs = person.userData
    person.scale.set(1, 1, 1)
    person.userData.pack.visible = true
    ;[limbs.legL, limbs.legR, limbs.armL, limbs.armR, limbs.kneeL, limbs.kneeR].forEach(
        (limb) => (limb.rotation.x = 0),
    )
}
