/**
 * HUD: fondo por ambiente, temporizador, objetivo actual.
 */
import { clamp, isTouch, qs, qsa } from '../core/utils.js'
import { content } from '../data/content.js'

export function setBackground(name) {
    qsa('#bg i').forEach((t) => t.classList.toggle('on', t.dataset.bg === name))
}
export function showTimer(visible) {
    qs('#timer').hidden = !visible
}
export function updateTimer(remaining, total) {
    let a = qs('#timer')
    a.querySelector('b').textContent = Math.max(0, Math.ceil(remaining))
    a.querySelector('u').style.transform = 'scaleX(' + clamp(remaining / total, 0, 1) + ')'
    a.classList.toggle('low', remaining <= 5)
}
export function setObjective(title, subtitle) {
    let a = qs('#objective')
    if (!title) {
        a.hidden = true
        return
    }
    qs('strong', a).textContent = title
    qs('small', a).textContent = subtitle || ''
    qs('small', a).hidden = !subtitle
    a.hidden = false
}

// ---- Recorrido por scroll: indicador, barra de progreso, vineta y titulo del objeto ----
let typingTimer = null

/** Muestra u oculta la ayuda "Desplazate para avanzar" y la barra de progreso lateral. */
export function showScrollHint(visible) {
    const hint = qs('#scrollHint')
    hint.hidden = !visible
    hint.classList.remove('quiet')
    qs('b', hint).textContent = isTouch ? content.scroll.hintTouch : content.scroll.hint
    qs('#tourRail').hidden = !visible
}
/** Ayuda de movimiento (abajo, al centro): aparece y se va desvaneciendo sola, como la del scroll. */
export function showMoveHint() {
    const el = qs('#moveHint')
    const text = content.controls
    el.innerHTML = isTouch
        ? '<span class="hl">' + text.touch + '</span>'
        : '<span class="mk"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd></span><i>' +
          text.or +
          '</i><span class="mk"><kbd>↑</kbd><kbd>←</kbd><kbd>↓</kbd><kbd>→</kbd></span><span class="hl">' +
          text.move +
          '</span><span class="sep"></span><span class="mk"><kbd>E</kbd></span><span class="hl">' +
          text.act +
          '</span>'
    el.hidden = false
    el.classList.remove('go')
    void el.offsetWidth // reinicia la animacion
    el.classList.add('go')
}
export function hideMoveHint() {
    const el = qs('#moveHint')
    el.hidden = true
    el.classList.remove('go')
}
/** La ayuda se atenua en cuanto el usuario empieza a avanzar. */
export function quietScrollHint() {
    qs('#scrollHint').classList.add('quiet')
}
/** progress: 0..1 del camino. closeness: 0..1 al acercarse al objeto. */
export function setTourProgress(progress, closeness) {
    qs('#tourRail i').style.transform = 'scaleY(' + progress.toFixed(3) + ')'
    qs('#vignette').style.opacity = (closeness * 0.9).toFixed(3)
    qs('#scrollHint').classList.toggle('gone', closeness > 0.85)
}
/** Titulo del objeto que se "escribe" letra a letra, como en el video de referencia. */
export function showStopLabel(title, sub) {
    const el = qs('#stopLabel')
    hideStopLabel()
    el.hidden = false
    el.classList.add('typing')
    const h = qs('h2', el)
    const p = qs('p', el)
    let i = 0
    typingTimer = setInterval(() => {
        i++
        if (i <= title.length) h.textContent = title.slice(0, i)
        else p.textContent = sub.slice(0, i - title.length)
        if (i >= title.length + sub.length) {
            clearInterval(typingTimer)
            typingTimer = null
        }
    }, 26)
}
export function hideStopLabel() {
    clearInterval(typingTimer)
    typingTimer = null
    const el = qs('#stopLabel')
    el.hidden = true
    el.classList.remove('typing')
    qs('h2', el).textContent = ''
    qs('p', el).textContent = ''
}
