/**
 * PASOS: Inicio -> Introduccion animada (start) -> entrada a la casa (walk, en before.js).
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { session, state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { goTo, steps } from './navigation.js'
import { setCameraMode, setOrbit } from '../systems/camera.js'
import { lockTour, startTour, tour } from '../systems/scrollTour.js'
import { cat, dog, placePet, setPetMood } from '../three/characters.js'
import { setDoorOpen } from '../three/livingRoom.js'
import { camera, mainScene } from '../three/renderer.js'
import { world } from '../three/world.js'
import { setBackground } from '../ui/hud.js'
import { showDynamic } from '../ui/panels.js'

/**
 * INICIO: un mundo sin fin (suelo que se pierde en el horizonte con niebla y nubes), sin la casa.
 * Al cargar, la camara empieza lejos y se acerca hasta la vista de la portada; el texto aparece en el
 * centro y Cacao y Nube quedan en las esquinas de abajo, sin tapar el texto.
 */
const HOME_FINAL = { r: 7.5, h: 3.2, ty: 1 } // camara de la portada (orbita alrededor de (0, ty, 0), mirando desde +z)
const HOME_START = { r: 30, h: 10 } // desde donde empieza a acercarse
const HOME_DOLLY = 4.6 // segundos que tarda en acercarse
const HOME_DELAY = 0.5 // espera inicial (mientras se va la pantalla de carga)
const homeWorld = { group: null, clouds: [], fog: null }
const homeEase = (k) => 1 - Math.pow(1 - Math.min(1, Math.max(0, k)), 3) // frena suave al llegar

/** Suelo infinito (un plano enorme con niebla) y nubes; se crea una sola vez. */
function buildHomeWorld() {
    if (homeWorld.group) return homeWorld
    const css = getComputedStyle(document.documentElement)
    const horizon = new THREE.Color(css.getPropertyValue('--bg2').trim() || '#e6f1ff')
    const group = new THREE.Group()
    // suelo liso: un solo color suave que se funde con el cielo en el horizonte (sin cuadros)
    const ground = new THREE.Mesh(
        new THREE.CircleGeometry(400, 48),
        new THREE.MeshStandardMaterial({
            color: horizon.clone().lerp(new THREE.Color('#ffffff'), 0.25),
            roughness: 1,
        }),
    )
    ground.rotation.x = -Math.PI / 2
    ground.receiveShadow = true
    group.add(ground)
    // nubes que pasan despacio
    const cloudMat = new THREE.MeshBasicMaterial({ color: '#ffffff', transparent: true, opacity: 0.92, fog: false })
    for (let i = 0; i < 16; i++) {
        const cloud = new THREE.Group()
        for (let k = 0; k < 4; k++) {
            const puff = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 10), cloudMat)
            puff.position.set((k - 1.5) * 1.5, Math.sin(k * 2.1) * 0.35, Math.cos(k * 1.7) * 0.4)
            puff.scale.set(1.6 - Math.abs(k - 1.5) * 0.25, 0.8, 1)
            cloud.add(puff)
        }
        const s = 1.2 + (i % 4) * 0.5
        cloud.scale.setScalar(s)
        cloud.position.set(-90 + ((i * 53) % 180), 9 + (i % 5) * 2.2, -20 - ((i * 37) % 90))
        cloud.userData.speed = 0.5 + (i % 3) * 0.3
        group.add(cloud)
        homeWorld.clouds.push(cloud)
    }
    // luz amarilla suave en el suelo, como una alfombra, con particulas que suben (mas tenue que la del final)
    const glowCanvas = document.createElement('canvas')
    glowCanvas.width = glowCanvas.height = 256
    const gc = glowCanvas.getContext('2d')
    const gradient = gc.createRadialGradient(128, 128, 0, 128, 128, 128)
    gradient.addColorStop(0, 'rgba(255,214,140,.9)')
    gradient.addColorStop(0.45, 'rgba(255,190,120,.35)')
    gradient.addColorStop(1, 'rgba(255,190,120,0)')
    gc.fillStyle = gradient
    gc.fillRect(0, 0, 256, 256)
    const glow = new THREE.Mesh(
        new THREE.PlaneGeometry(10, 10),
        new THREE.MeshBasicMaterial({
            map: new THREE.CanvasTexture(glowCanvas),
            transparent: true,
            opacity: 0.38,
            depthWrite: false,
            blending: THREE.AdditiveBlending,
            fog: false,
        }),
    )
    glow.rotation.x = -Math.PI / 2
    glow.position.set(0, 0.02, 0.6)
    const rug = new THREE.Mesh(
        new THREE.RingGeometry(3.3, 3.42, 64),
        new THREE.MeshBasicMaterial({
            color: '#ffd27a',
            transparent: true,
            opacity: 0.22,
            side: THREE.DoubleSide,
            depthWrite: false,
            fog: false,
        }),
    )
    rug.rotation.x = -Math.PI / 2
    rug.position.set(0, 0.025, 0.6)
    const count = 80
    const positions = new Float32Array(count * 3)
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2
        const radius = 4.2 * Math.sqrt(Math.random())
        positions.set([Math.cos(angle) * radius, Math.random() * 4.5, 0.6 + Math.sin(angle) * radius], i * 3)
    }
    const motesGeometry = new THREE.BufferGeometry()
    motesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    const motes = new THREE.Points(
        motesGeometry,
        new THREE.PointsMaterial({
            color: '#ffd27a',
            size: 0.09,
            transparent: true,
            opacity: 0.45,
            depthWrite: false,
            blending: THREE.AdditiveBlending,
            fog: false,
        }),
    )
    motes.frustumCulled = false
    group.add(glow, rug, motes)
    homeWorld.motes = motes
    homeWorld.fog = new THREE.Fog(horizon, 24, 130)
    homeWorld.group = group
    mainScene.add(group)
    return homeWorld
}

/** Coloca a Cacao y Nube en el suelo, en las esquinas de abajo de la camara final de la portada. */
function layoutHomePets() {
    const narrow = innerWidth < 720
    const nx = narrow ? 0.66 : 0.74
    const ny = narrow ? -0.8 : -0.62
    const scale = narrow ? 0.7 : 1
    const cam = new THREE.PerspectiveCamera(34, innerWidth / innerHeight, 0.1, 200)
    cam.position.set(0, HOME_FINAL.h, HOME_FINAL.r)
    cam.lookAt(0, HOME_FINAL.ty, 0)
    cam.updateMatrixWorld()
    cam.updateProjectionMatrix()
    // rayo desde la camara hacia la esquina; donde toca el suelo (y = 0) se apoya la mascota
    const ground = (x, y) => {
        const ray = new THREE.Vector3(x, y, 0.5).unproject(cam).sub(cam.position)
        return cam.position.clone().addScaledVector(ray, -cam.position.y / ray.y)
    }
    const left = ground(-nx, ny)
    const right = ground(nx, ny)
    placePet(dog, left.x, 0, left.z, 0.55, scale)
    placePet(cat, right.x, 0, right.z, -0.55, scale)
}

steps.home = {
    stage: 0,
    w: 0,
    layout: layoutHomePets, // al cambiar el tamano de la ventana
    enter() {
        setCameraMode('orbit')
        world.root.visible = false // sin casa
        setBackground('day')
        const wrld = buildHomeWorld()
        wrld.group.visible = true
        mainScene.fog = wrld.fog
        dog.visible = cat.visible = true
        setPetMood(dog, { wag: 2.4, eyes: 1.1 })
        setPetMood(cat, { wag: 2, eyes: 1.1 })
        layoutHomePets()
        // la camara empieza lejos y alta, y se acerca hasta la vista de la portada
        const setCamera = (k) =>
            setOrbit({
                theta: Math.PI / 2,
                r: HOME_START.r + (HOME_FINAL.r - HOME_START.r) * k,
                h: HOME_START.h + (HOME_FINAL.h - HOME_START.h) * k,
                ty: HOME_FINAL.ty,
                speed: 0,
                amp: 0,
            })
        setCamera(0)
        let time = -HOME_DELAY
        let hopAt = HOME_DOLLY + 0.5
        state.curTick = (dt) => {
            time += dt
            setCamera(homeEase(time / HOME_DOLLY))
            wrld.clouds.forEach((cloud) => {
                cloud.position.x += cloud.userData.speed * dt
                if (cloud.position.x > 100) cloud.position.x = -100
            })
            // las particulas amarillas suben despacio desde el suelo y vuelven a empezar abajo
            const spots = wrld.motes.geometry.attributes.position
            for (let i = 0; i < spots.count; i++) {
                let y = spots.getY(i) + dt * (0.22 + (i % 5) * 0.07)
                if (y > 4.8) y = 0
                spots.setY(i, y)
                spots.setX(i, spots.getX(i) + Math.sin(state.time * 0.8 + i) * 0.0015)
            }
            spots.needsUpdate = true
            if (time > hopAt) {
                hopAt = time + 3.2
                ;(Math.random() < 0.5 ? dog : cat).userData.hop = 1
            }
        }
        state.curExit = () => {
            wrld.group.visible = false
            mainScene.fog = null
        }
        qs('#home').classList.add('active')
        qs('#hud').hidden = false
    },
}

/**
 * INTRODUCCION ANIMADA, ultimo paso antes de entrar a la casa.
 * Vista frontal del vecindario: la camara es una persona que cruza la calle y camina por el jardin
 * hasta la puerta (la del .glb). Mientras camina, la informacion de la experiencia aparece como frases
 * sueltas en distintos lugares de la pantalla (content.start.beats). Al llegar aparece el boton:
 * al pulsarlo se reproduce la animacion de apertura de la puerta (hecha en Blender) y el recorrido
 * sigue hacia adentro sin corte (paso walk).
 */
const WALK_TIME = 8.5 // segundos que dura la caminata hasta la puerta
const CTA_AT = 7.8 // segundo en que aparece el boton (ver css/17-introduccion.css)
// Camino (x, z en metros): en linea recta y de frente a la casa, desde la calle hasta 1.8 m de la puerta
// (la puerta esta en x 3.46, z -2). Calle en x 13..19, aceras en 11..13 y 19..21.
const INTRO_PATH = [
    { x: 14.5, z: -2 },
    { x: 5.3, z: -2 },
]
const DOOR_LOOK = [3.46, 1.05, -2]
const SEISMO_PATH =
    'M0 30 H110 L120 27 L128 34 L136 24 L146 38 L156 20 L168 42 L180 14 L194 48 L208 8 L224 52 L240 4 L258 56 L276 30 H520'

steps.start = {
    stage: 1, // la introduccion es el comienzo del "Antes"
    w: 0,
    prev: 'home',
    next: () => qs('.introfx .cta')?.click(), // abre la puerta y entra a la casa
    enter() {
        session.greeted = false
        session.enterSmooth = false
        dog.visible = cat.visible = false // estan dentro de la casa: aparecen al abrir la puerta
        setCameraMode('fp')
        setDoorOpen(false, true)
        setPetMood(dog, {})
        setPetMood(cat, {})
        // La camara camina sola (como una persona): el scroll no interviene
        startTour({ path: INTRO_PATH, look: DOOR_LOOK, closeFrom: 0.85, lookDown: 0.6 })
        lockTour()

        const text = content.start
        const beats = text.beats
            .map(
                (b) =>
                    '<div class="beat ' +
                    b.pos +
                    (b.hold ? ' hold' : '') +
                    '" style="--at:' +
                    b.at +
                    's;--dur:' +
                    b.dur +
                    's">' +
                    '<span class="small">' +
                    b.small +
                    '</span><span class="big">' +
                    b.big +
                    '</span></div>',
            )
            .join('')
        const el = showDynamic(
            '<div class="introfx" style="--cta:' +
                CTA_AT +
                's">' +
                beats +
                '<svg class="introline" viewBox="0 0 520 60" aria-hidden="true"><path pathLength="1" d="' +
                SEISMO_PATH +
                '"/></svg>' +
                '<button class="btn big cta">' +
                text.cta +
                '</button></div>',
        )
        let opening = false
        qs('.cta', el).addEventListener('click', () => {
            if (opening) return
            opening = true
            audio.blip()
            audio.creak()
            qs('.introfx', el).classList.add('out')
            setDoorOpen(true) // se reproduce la animacion de la puerta hecha en Blender
            session.enterSmooth = true // el siguiente paso continua la camara sin corte
            setTimeout(() => goTo('walk'), 1700)
        })

        // Camina hasta la puerta; al llegar, alguien ladra y maulla adentro
        let time = 0
        let dogHi = false
        let catHi = false
        state.curTick = (dt) => {
            time += dt
            if (!opening) tour.target = Math.min(1, time / WALK_TIME)
            if (!dogHi && time > WALK_TIME - 0.6) {
                dogHi = true
                audio.bark()
            }
            if (!catHi && time > WALK_TIME + 0.1) {
                catHi = true
                audio.meow()
            }
        }
    },
}
