/**
 * PASOS de la etapa ANTES: recorrido por la casa, kit, mascota, rastreo.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { session, state } from '../core/state.js'
import { isTouch, qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { showCenterPanel, startInfoTour } from './helpers.js'
import { seatY } from './sofaScene.js'
import { goTo, steps, transitionTo } from './navigation.js'
import { enterStage, focusOn, fovBoost, setCameraMode, setOrbit, showCam, stage } from '../systems/camera.js'
import { startPetting, stopPetting } from '../systems/petting.js'
import { startTour } from '../systems/scrollTour.js'
import { livingRoom, setDoorOpen } from '../three/livingRoom.js'
import { setBeacon, setInteract } from '../systems/interaction.js'
import { player, resetPlayer } from '../systems/player.js'
import { resetBooks } from '../systems/quakeEffects.js'
import { cat, dog, person, placePet, popIn, setPetMood, walkPath } from '../three/characters.js'
import {
    emergeKitItems,
    resetKitItems,
    setKitOpen,
    showCameras,
    showrooms,
    storeKitItem,
} from '../three/showrooms.js'
import { addHotspot, clearHotspots } from '../ui/hotspots.js'
import { hideStopLabel, setObjective, showScrollHint, showStopLabel } from '../ui/hud.js'
import { setControlsHint, showDynamic } from '../ui/panels.js'

// ---- Escenario de primera persona: la sala exportada de Blender (static/casa.glb, ver three/livingRoom.js) ----
// Medidas en metros. La sala va de x -2 a 3.4 y de z -2.9 a 2.9. Se entra por la puerta de la pared
// derecha (x 3.45, z -2), desde la terraza. Detras del tabique del televisor (z -1.3) hay una franja
// hasta la mesa de primeros auxilios (esquina izquierda del fondo); se rodea el tabique por el hueco
// de la izquierda (x -2 a -0.1) para llegar al sofa, que esta al frente (z 2.3) y mira al televisor.
const DOG_SCALE = 0.42
const CAT_SCALE = 0.4
const DOG_SPOT = { x: 1.15, z: 2.3 } // Cacao en el sofa
const CAT_SPOT = { x: 1.85, z: 2.3 } // Nube junto a Cacao
const placeOnSofa = () => {
    placePet(dog, DOG_SPOT.x, seatY(), DOG_SPOT.z, Math.PI, DOG_SCALE)
    placePet(cat, CAT_SPOT.x, seatY(), CAT_SPOT.z, Math.PI, CAT_SCALE)
}

// ---- Caminos del recorrido por scroll (x, z en metros) ----
// 1) Saludo: entrar por la puerta de la derecha y quedar frente a las mascotas.
const GREET_PATH = [
    { x: 5.3, z: -2 },
    { x: 2.6, z: -2 },
]
const GREET_LOOK = [1.3, 0.3, -2] // punto entre las dos mascotas
// 2) Pasillo del fondo, hasta la mesa de primeros auxilios.
const KIT_PATH = [
    { x: 2.6, z: -2 },
    { x: 1, z: -2 },
    { x: -0.55, z: -2.05 },
]
const KIT_LOOK = [-1.75, 0.75, -2.15] // el kit sobre la mesa
// 3) De la mesa al sofa, rodeando el tabique por la izquierda (paso petwalk).
const PET_PATH = [
    { x: -0.55, z: -2.05 }, // donde se quedo la camara al abrir el kit: de ahi sigue el recorrido
    { x: -1, z: -0.5 }, // ya pasado el tabique del televisor: desde aqui se ven las mascotas sin la pared
    { x: -0.6, z: 0.4 },
    { x: 0.1, z: 1 },
    { x: 0.75, z: 1.45 },
]
const PET_LOOK = [1.5, 0.8, 2.3] // punto entre Cacao y Nube

// Las mascotas bajan del sofa, rodean el tabique y corren hacia la puerta a recibir al usuario
const GREET_DOG = [
    { x: 0.2, z: 1.6 },
    { x: -1, z: 0.8 },
    { x: -1, z: -1.9 },
    { x: 1.3, z: -2.3, ry: Math.PI / 2 },
]
const GREET_CAT = [
    { x: 0.4, z: 1.9 },
    { x: -0.9, z: 0.9 },
    { x: -0.9, z: -1.8 },
    { x: 1.3, z: -1.7, ry: Math.PI / 2 },
]
// Y vuelven al sofa cuando el usuario entra a la casa
const DOG_WALK = [
    { x: -1, z: -1.9 },
    { x: -1, z: 0.9 },
    { x: 0.8, z: 2 },
    { x: DOG_SPOT.x, z: DOG_SPOT.z, get y() { return seatY() }, ry: Math.PI },
]
const CAT_WALK = [
    { x: -0.9, z: -1.8 },
    { x: -0.9, z: 1 },
    { x: 1, z: 2.1 },
    { x: CAT_SPOT.x, z: CAT_SPOT.z, get y() { return seatY() }, ry: Math.PI },
]

steps.walk = {
    stage: 1,
    w: 0.05,
    prev: 'start',
    next: 'kit',
    enter() {
        setCameraMode('fp')
        resetBooks()
        const walkText = content.walk
        let phase = 0 // fases del recorrido hacia el kit: 0 puerta, 1 sala, 2 cerca del kit, 3 frente al kit

        // ---- Recorrido hacia el kit ----
        const onKitProgress = (p) => {
            if (phase < 1 && p > 0.3) {
                phase = 1
                setBeacon(null)
                setObjective(walkText.a.t, walkText.a.s)
            }
            if (phase < 2 && p > 0.55) {
                phase = 2
                setObjective(walkText.b.t, walkText.b.s)
                setBeacon(-1.75, -2.15, 1.2, 0.4) // marca pequena, justo encima del kit
                audio.ding()
            }
            if (phase < 3 && p > 0.95) {
                phase = 3
                showStopLabel(walkText.stop.t, walkText.stop.s)
                setInteract({ x: -1.75, z: -2.15, r: 1.6, label: walkText.open, fn: () => goTo('kit') })
            } else if (phase === 3 && p < 0.9) {
                phase = 2
                hideStopLabel()
                setInteract(null)
            }
        }
        const beginKitTour = (startAt) => {
            showScrollHint(true)
            startTour({ path: KIT_PATH, look: KIT_LOOK, startAt, lookDown: 0.85, onProgress: onKitProgress })
        }

        setPetMood(dog, {})
        setPetMood(cat, {})
        setDoorOpen(true, session.greeted)
        // Si ya saludaron una vez, el usuario aparece directamente dentro de la sala.
        if (session.greeted) {
            placeOnSofa()
            dog.visible = cat.visible = true
            phase = 1
            setObjective(walkText.a.t, walkText.a.s)
            beginKitTour(0.4)
            return
        }

        // ---- Saludo: la puerta se abre, las mascotas corren a recibirte y te acercas con el scroll ----
        session.greeted = true
        placeOnSofa() // esperan en el sofa y salen a recibir al usuario
        dog.visible = cat.visible = true
        setObjective(walkText.greet.t, walkText.greet.s)

        const pills = [
            addHotspot({
                cls: 'pill',
                label: 'Cacao',
                anchor: dog.userData.anchors.head,
                onClick: () => {
                    dog.userData.hop = 1
                    audio.bark()
                },
            }),
            addHotspot({
                cls: 'pill',
                label: 'Nube',
                anchor: cat.userData.anchors.head,
                onClick: () => {
                    cat.userData.hop = 1
                    audio.meow()
                },
            }),
        ]
        pills.forEach((b) => (b.hidden = true))

        const enterHouse = () => {
            clearHotspots()
            hideStopLabel()
            setInteract(null)
            state.curTick = null // dejan de saludar: ya no ladran, saltan ni mueven la cola de emocion
            setPetMood(dog, {})
            setPetMood(cat, {})
            walkPath(dog, DOG_WALK, 3.4)
            walkPath(cat, CAT_WALK, 3.9)
            setObjective(walkText.hall.t, walkText.hall.s)
            beginKitTour(0)
            audio.blip()
        }
        let atPets = false
        let greetUser = () => {}
        showScrollHint(true)
        startTour({
            path: GREET_PATH,
            look: GREET_LOOK,
            closeFrom: 0.35,
            continueLook: session.enterSmooth, // viene de la introduccion: sigue mirando la puerta y gira hacia las mascotas
            lookDown: 0.95, // las mascotas son bajas: la mirada baja hasta ellas
            onProgress: (p) => {
                if (!atPets && p > 0.95) {
                    atPets = true
                    pills.forEach((b) => (b.hidden = false))
                    greetUser() // saludan al usuario cuando llega
                    showStopLabel(walkText.greetStop.t, walkText.greetStop.s)
                    setInteract({ x: 1.3, z: -2, r: 2.2, label: walkText.enter, fn: enterHouse })
                } else if (atPets && p < 0.9) {
                    atPets = false
                    pills.forEach((b) => (b.hidden = true))
                    hideStopLabel()
                    setInteract(null)
                }
            },
        })
        // Las mascotas corren a saludar: ladran, maullan, mueven la cola y saltan de alegria
        let elapsed = 0
        let dogGo = false
        let catGo = false
        let dogArrived = false
        let catArrived = false
        let cheer = 0
        const cheerUp = () => {
            dog.userData.hop = 1
            audio.bark()
            setTimeout(() => {
                cat.userData.hop = 1
                audio.meow()
            }, 420)
        }
        greetUser = cheerUp
        state.curTick = (dt) => {
            elapsed += dt
            if (!dogGo && elapsed > 0.7) {
                dogGo = true
                walkPath(dog, GREET_DOG, 3.8)
                setPetMood(dog, { wag: 2.6, eyes: 1.1 })
                audio.bark()
            }
            if (!catGo && elapsed > 1.4) {
                catGo = true
                walkPath(cat, GREET_CAT, 3.4)
                setPetMood(cat, { wag: 2.4, eyes: 1.1 })
                audio.meow()
            }
            if (dogGo && !dogArrived && !dog.userData.walking) {
                dogArrived = true
                dog.userData.hop = 1
                audio.bark()
            }
            if (catGo && !catArrived && !cat.userData.walking) {
                catArrived = true
                cat.userData.hop = 1
                audio.meow()
            }
            // ya con el usuario cerca, siguen celebrando de vez en cuando
            if (dogArrived && catArrived) {
                cheer += dt
                if (cheer > 2.6) {
                    cheer = 0
                    cheerUp()
                }
            }
        }
    },
}
// Donde se monta el kit animado: sobre la mesa de primeros auxilios (el tamano de la mochila de la mesa)
const KIT_TABLE = new THREE.Vector3(-1.75, 0.58, -2.15)
const KIT_SCALE = 0.22
const KIT_EYE_DIST = 5.45 // distancia (en unidades de la vitrina) de la camara al kit cuando se llega caminando
steps.kit = {
    stage: 1,
    w: 0.4,
    prev: 'walk',
    next: () => state.stepData.exitKit && state.stepData.exitKit('petwalk'),
    enter() {
        // El kit se abre en la misma sala, sobre la mesa: la camara sigue donde estaba y no hay corte ni fondo aparte
        setCameraMode('stage')
        livingRoom.bag.visible = false // la mochila de la mesa se reemplaza por la animada
        enterStage('kit', KIT_TABLE, KIT_SCALE, 0.12)
        state.curExit = () => (livingRoom.bag.visible = true)
        const kitRoom = showrooms.kit
        const kitText = content.kit
        let leaving = false
        // Al terminar, la camara vuelve a la pose con la que se llego al kit y entonces sigue el recorrido
        state.stepData.exitKit = (target) => {
            if (leaving) return
            leaving = true
            setKitOpen(false)
            focusOn(null)
            state.showRot = 0
            showCam.follow = null
            showCam.goalT = [0, 0.77, 0]
            showCam.goalD = KIT_EYE_DIST
            stage.liftGoal = 1.4 - (KIT_TABLE.y + KIT_SCALE * (0.77 + KIT_EYE_DIST * 0.14))
            fovBoost.t = 0.9
            setTimeout(() => {
                if (state.cur !== 'kit') return
                fovBoost.t = 0
                goTo(target)
            }, 1300)
        }
        // La mochila cae y se abre; los objetos salen de ella uno por uno mientras la camara
        // da una vuelta y se aleja. Al ver un objeto, la camara lo sigue de vuelta a la mochila.
        resetKitItems()
        const total = kitText.items.length
        const tourUi = startInfoTour({
            title: kitText.title,
            text: kitText.text,
            zoom: 5.4,
            autoNext: true, // cada objeto se guarda en la mochila al cerrarlo
            backLabel: 'Ver otros objetos',
            items: kitText.items.map((item, i) => ({ anchor: kitRoom.items[i].userData.anchor, ...item })),
            next: () => state.stepData.exitKit('petwalk'),
            onPick: (i) => kitRoom.items.forEach((item, k) => (item.userData.sel = i === k)),
            onSeen: (i) => {
                // El objeto vuela a la mochila y la camara lo acompana, luego se queda en la mochila
                storeKitItem(i)
                focusOn(kitRoom.items[i].userData.anchor, 6)
                setTimeout(() => focusOn(kitRoom.bagAnchor, 6.6), 480)
                if (tourUi.seen.size === total) setTimeout(() => setKitOpen(false), 700) // se cierra al guardar el ultimo
                return 1200
            },
        })
        emergeKitItems()
        audio.blip()

        // Secuencia de camara de la entrada (0 a 6.5 s). Se detiene si el usuario ya abrio un objeto.
        const ease = (x) => {
            const k = Math.min(1, Math.max(0, x))
            return k * k * (3 - 2 * k)
        }
        const lerp = (a, b, k) => a + (b - a) * k
        let time = 0
        let opened = false
        const home = showCameras.kit
        state.curTick = (dt) => {
            time += dt
            kitRoom.items.forEach((item, i) => {
                tourUi.buttons[i].hidden = item.userData.stage !== 'out'
            })
            if (!opened && time > 1.45) {
                opened = true
                setKitOpen(true)
                fovBoost.t = 0.3 // pequeno "golpe" de zoom al abrir
                setTimeout(() => (fovBoost.t = 0), 450)
                audio.ding()
            }
            if (time > 6.6 || tourUi.opened.size > 0 || leaving) return
            if (time < 1.6) {
                // cerca de la mochila mientras cae
                const k = ease(time / 1.6)
                state.showRot = lerp(-1.4, -0.5, k)
                showCam.goalD = lerp(5.8, 6.6, k)
                showCam.goalT = [0, lerp(1.6, 1.0, k), 0]
            } else if (time < 5.6) {
                // da una vuelta y se aleja mientras salen los objetos
                const k = ease((time - 1.6) / 4)
                state.showRot = lerp(-0.5, 0.5, k)
                showCam.goalD = lerp(6.6, home.d + 0.6, k)
                showCam.goalT = [0, lerp(1.0, 1.3, k), 0]
            } else {
                const k = ease((time - 5.6) / 1)
                state.showRot = lerp(0.5, 0, k)
                showCam.goalD = lerp(home.d + 0.6, home.d, k)
                showCam.goalT = [0, lerp(1.3, home.t[1], k), 0]
            }
        }
    },
}
steps.petwalk = {
    stage: 1,
    w: 0.6,
    prev: 'kit',
    next: 'track',
    enter() {
        setCameraMode('fp')
        setDoorOpen(true, true)
        const petwalkText = content.petwalk
        placeOnSofa()
        setPetMood(dog, {})
        setPetMood(cat, {})
        dog.visible = cat.visible = true
        setObjective(petwalkText.t, petwalkText.s)
        setBeacon(1.5, 2.3, 1.35, 0.4) // marca pequena encima de las mascotas
        showScrollHint(true)

        // Acercarse con el scroll a las dos mascotas y, al llegar, acariciar a Cacao y luego a Nube
        let atPets = false
        startTour({
            path: PET_PATH,
            look: PET_LOOK,
            lookDown: 0.85,
            introFrom: KIT_LOOK, // empieza en el kit, mirandolo, y gira sola hacia el camino; luego sigue el scroll
            onProgress: (p) => {
                if (!atPets && p > 0.95) {
                    atPets = true
                    showStopLabel(petwalkText.stop.t, petwalkText.stop.s)
                    setInteract({
                        x: 1.5,
                        z: 2.3,
                        r: 2.4,
                        label: petwalkText.open,
                        fn: () => {
                            hideStopLabel()
                            setObjective(null)
                            setBeacon(null)
                            showScrollHint(false)
                            state.curExit = stopPetting
                            state.curTick = startPetting([dog, cat], () => goTo('track'))
                        },
                    })
                } else if (atPets && p < 0.9) {
                    atPets = false
                    hideStopLabel()
                    setInteract(null)
                }
            },
        })
        audio.bark()
    },
}
steps.track = {
    stage: 1,
    w: 0.72,
    prev: 'petwalk',
    next: 'trackCat',
    enter() {
        // Cacao se muestra en el sofa de la sala: la camara sigue donde quedo despues de las caricias
        setCameraMode('stage')
        setDoorOpen(true, true)
        placeOnSofa()
        dog.visible = false // en su lugar se ve el Cacao del rastreo, del mismo tamano
        cat.visible = true
        setPetMood(cat, {})
        enterStage('track', new THREE.Vector3(DOG_SPOT.x, seatY() + 0.005, DOG_SPOT.z), DOG_SCALE / 2.1, 0.15)
        state.curExit = () => (dog.visible = cat.visible = true)
        let e = showrooms.track.dog.userData.anchors,
            trackText = content.track
        setPetMood(showrooms.track.dog, {})
        startInfoTour({
            title: trackText.title,
            text: trackText.text,
            zoom: 4.4,
            backLabel: 'Ver otros puntos',
            items: [e.tag, e.gps, e.chip].map((a, o) =>
                Object.assign(
                    {
                        anchor: a,
                        rot: [0, -1, Math.PI * 0.9][o],
                    },
                    trackText.items[o],
                ),
            ),
            next: () => goTo('trackCat'),
        })
    },
}
steps.trackCat = {
    stage: 1,
    w: 0.85,
    prev: 'track',
    next: 'antesEnd',
    enter() {
        // Nube se muestra en el sofa, junto a Cacao, sin cambiar de escenario
        setCameraMode('stage')
        setDoorOpen(true, true)
        placeOnSofa()
        dog.visible = true
        cat.visible = false
        setPetMood(dog, {})
        enterStage('trackCat', new THREE.Vector3(CAT_SPOT.x, seatY() + 0.005, CAT_SPOT.z), CAT_SCALE / 2.7, 0.15)
        state.curExit = () => (dog.visible = cat.visible = true)
        const anchors = showrooms.trackCat.cat.userData.anchors
        const trackText = content.trackCat
        setPetMood(showrooms.trackCat.cat, {})
        startInfoTour({
            title: trackText.title,
            text: trackText.text,
            zoom: 4.4,
            backLabel: 'Ver otros puntos',
            items: [anchors.tag, anchors.gps, anchors.chip].map((a, i) => ({
                anchor: a,
                rot: [0, -1, Math.PI * 0.9][i],
                ...trackText.items[i],
            })),
            next: () => goTo('antesEnd'), // sin corte: la camara sale de la cabeza del usuario
        })
    },
}
