/**
 * PASOS de la etapa DESPUES: primeros auxilios (en el escenario de afuera de la casa) y quiz.
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { clamp, qs, qsa, shuffle } from '../core/utils.js'
import { content } from '../data/content.js'
import { petFaces } from '../data/icons.js'
import { illustrations } from '../data/illustrations.js'
import { goTo, steps } from './navigation.js'
import { cineGo, cineSet, cineStart, setCameraMode, setOrbit, showRoom } from '../systems/camera.js'
import { cat, dog, person, placePet, setPetMood } from '../three/characters.js'
import { setDoorOpen } from '../three/livingRoom.js'
import { showrooms } from '../three/showrooms.js'
import { showDynamic } from '../ui/panels.js'
import { resetPerson } from './sofaScene.js'

// ---- Afuera de la casa: el mismo escenario con el que empieza el "Antes" (la calle y el porche) ----
const OUT_FROM = new THREE.Vector3(10.6, 1.65, -2.35) // la camara empieza lejos y se acerca despacio
const OUT_TO = new THREE.Vector3(8.4, 1.5, -2.2)
const OUT_LOOK = new THREE.Vector3(4.6, 1.0, -2)
const OUT_SECONDS = 28 // lo que tarda en acercarse
let outsideTime = 0
const outsideDrift = (dt) => {
    outsideTime += dt
    cineGo(OUT_FROM.clone().lerp(OUT_TO, clamp(outsideTime / OUT_SECONDS, 0, 1)), OUT_LOOK, 1.6)
}

/** El usuario y sus mascotas, ya afuera, frente a la puerta cerrada, mirando hacia la camara. */
function placeOutside() {
    setDoorOpen(false, true)
    resetPerson()
    person.visible = true
    person.scale.setScalar(0.85)
    person.position.set(5.4, 0, -2.05)
    person.rotation.y = Math.PI / 2
    placePet(dog, 5.2, 0, -3.05, Math.PI / 2 - 0.3, 0.5)
    placePet(cat, 5.2, 0, -1.05, Math.PI / 2 + 0.3, 0.48)
    dog.visible = cat.visible = true
    setPetMood(dog, { wag: 1.8, eyes: 1.05 })
    setPetMood(cat, { wag: 1.4, eyes: 1.05 })
    state.curExit = () => {
        resetPerson()
        dog.visible = cat.visible = true
    }
}

steps.despIntro = {
    stage: 3,
    w: 0.05,
    prev: 'sizePick',
    next: 'guide',
    enter() {
        setCameraMode('cine')
        cineSet(OUT_FROM, OUT_LOOK)
        outsideTime = 0
        placeOutside()
        state.curTick = outsideDrift
        // la misma decoracion del texto de cierre del "Antes": etiqueta, titulo y texto que aparecen uno tras otro
        const text = content.despIntro
        const el = showDynamic(
            '<div class="closefx quick"><span class="kick">' +
                text.kick +
                '</span><h2>' +
                text.title +
                '</h2><p>' +
                text.text +
                '</p><button class="btn big cta">' +
                text.cta +
                '</button></div>',
        )
        qs('.cta', el).addEventListener('click', () => {
            audio.blip()
            goTo('guide')
        })
    },
}

// Mochila del kit (dibujo) que sube desde abajo de la pantalla
const KIT_BAG =
    '<svg class="kitbag" viewBox="0 0 220 210" aria-hidden="true">' +
    '<path d="M78 42c0-22 12-34 32-34s32 12 32 34" fill="none" stroke="#14305e" stroke-width="9" stroke-linecap="round"/>' +
    '<rect x="14" y="36" width="192" height="172" rx="52" fill="#ff7a66"/>' +
    '<rect x="14" y="36" width="192" height="70" rx="34" fill="#ff917f"/>' +
    '<rect x="52" y="116" width="116" height="78" rx="20" fill="#ffc24d"/>' +
    '<path d="M110 130v50M85 155h50" stroke="#fff" stroke-width="13" stroke-linecap="round"/>' +
    '<path d="M60 70h100" stroke="#14305e" stroke-width="6" stroke-linecap="round" opacity=".35"/>' +
    '</svg>'

steps.guide = {
    stage: 3,
    w: 0.4,
    prev: 'despIntro',
    next: 'quiz',
    enter() {
        // sigue en el mismo lugar de afuera: el kit sale de abajo y de el sale una hoja con los primeros auxilios
        const wasCine = state.mode === 'cine'
        setCameraMode('cine')
        if (!wasCine) {
            cineSet(OUT_FROM, OUT_LOOK)
            outsideTime = 0
        } else cineStart()
        placeOutside()
        state.curTick = outsideDrift
        const guideText = content.guide
        const step = (p, i) =>
            '<div class="fa"><figure>' +
            illustrations[p.ill]() +
            '<span class="n">' +
            (i + 1) +
            '</span></figure><div><h3>' +
            p.t +
            '</h3><p>' +
            p.d +
            '</p></div></div>'
        // una columna por mascota: perros a la izquierda y gatos a la derecha
        const column = (tab, pet) =>
            '<section class="gcol"><header>' +
            petFaces[pet] +
            '<h2>' +
            tab.title +
            '</h2></header><p class="gintro">' +
            tab.intro +
            '</p>' +
            tab.steps.map(step).join('') +
            '<p class="end">Fin de la sección</p></section>'
        const root = showDynamic(
            '<div class="kitrise"><div class="sheet" role="document"><div class="sheetcols">' +
                column(guideText.tabs[0], 'dog') +
                column(guideText.tabs[1], 'cat') +
                '</div><div class="sheetfoot"><p id="gMsg">' +
                guideText.hint +
                '</p><button class="btn" id="gNext">Continuar</button></div></div>' +
                KIT_BAG +
                '</div>',
        )
        // el kit sube; un poco despues sale la hoja
        audio.whoosh()
        setTimeout(() => state.cur === 'guide' && audio.ding(), 1500)
        const seen = new Set()
        const io = new IntersectionObserver(
            (entries) =>
                entries.forEach((entry) => {
                    if (!entry.isIntersecting || entry.target.dataset.seen) return
                    entry.target.dataset.seen = 1
                    entry.target.classList.add('ok')
                    seen.add(entry.target)
                    audio.ding()
                    // Continuar siempre esta disponible; el mensaje solo avisa si falta leer
                    if (seen.size >= 2) qs('#gMsg', root).textContent = guideText.done
                }),
            { threshold: 0.9 },
        )
        qsa('.gcol .end', root).forEach((end) => io.observe(end))
        state.stepData.io = io
        // al continuar, la hoja se cierra y se mete otra vez en el kit, que baja; entonces sigue la retroalimentacion
        let closing = false
        qs('#gNext', root).addEventListener('click', () => {
            if (closing) return
            closing = true
            audio.blip()
            qs('.kitrise', root).classList.add('closing')
            setTimeout(() => state.cur === 'guide' && goTo('quiz'), 2300)
        })
    },
}
/**
 * RETROALIMENTACION: en el mismo escenario de afuera (desenfocado). La pregunta se escribe como a maquina y,
 * cuando termina, las tarjetas con las respuestas aparecen una despues de la otra, centradas en la pagina.
 */
steps.quiz = {
    stage: 3,
    w: 0.8,
    prev: 'guide',
    next: 'close',
    enter() {
        const wasCine = state.mode === 'cine'
        setCameraMode('cine')
        if (!wasCine) {
            cineSet(OUT_FROM, OUT_LOOK)
            outsideTime = 0
        } else cineStart()
        placeOutside()
        state.curTick = outsideDrift
        document.body.classList.add('blurred')
        const quizText = content.quiz
        const letters = ['a', 'b', 'c']
        const order = shuffle([0, 1, 2])
        const root = showDynamic(
            '<div class="quiz"><div class="qcard card"><h2 class="qtype" aria-label="' +
                quizText.q +
                '"></h2><p class="qhint">' +
                quizText.hint +
                '</p></div><div class="flips">' +
                order
                    .map((index, position) => {
                        const option = quizText.opts[index]
                        return (
                            '<button class="flip" data-ok="' +
                            (option.ok ? 1 : 0) +
                            '" aria-label="Opción ' +
                            letters[position] +
                            '"><span class="face front"><b>' +
                            letters[position] +
                            '</b><span>' +
                            option.text +
                            '</span></span><span class="face back ' +
                            (option.ok ? 'ok' : 'no') +
                            '"><strong>' +
                            (option.ok ? quizText.good : quizText.bad) +
                            '</strong><span>' +
                            option.fb +
                            '</span></span></button>'
                        )
                    })
                    .join('') +
                '</div><div class="quizfoot"><button class="btn" id="qNext" disabled>' +
                quizText.cta +
                '</button><small id="qMsg">' +
                quizText.wait +
                '</small></div></div>',
        )

        // la pregunta se escribe letra por letra; luego aparecen las tarjetas una tras otra
        const title = qs('.qtype', root)
        const timers = []
        let typed = 0
        const typer = setInterval(() => {
            typed++
            title.textContent = quizText.q.slice(0, typed)
            if (typed >= quizText.q.length) {
                clearInterval(typer)
                title.classList.add('done')
                timers.push(setTimeout(() => qs('.qhint', root).classList.add('show'), 300))
                qsa('.flip', root).forEach((card, i) =>
                    timers.push(
                        setTimeout(() => {
                            card.classList.add('in')
                            audio.blip()
                        }, 700 + i * 650),
                    ),
                )
                timers.push(setTimeout(() => qs('.quizfoot', root).classList.add('in'), 700 + 3 * 650))
            }
        }, 26)
        const leave = state.curExit
        state.curExit = () => {
            clearInterval(typer)
            timers.forEach(clearTimeout)
            document.body.classList.remove('blurred')
            if (leave) leave()
        }

        qsa('.flip', root).forEach((card) =>
            card.addEventListener('click', () => {
                if (card.classList.contains('flipped')) return
                card.classList.add('flipped')
                if (card.dataset.ok === '1') {
                    audio.ok()
                    qs('#qNext', root).disabled = false
                    qs('#qMsg', root).textContent = ''
                    cat.userData.hop = 1
                    dog.userData.hop = 1
                } else {
                    audio.no()
                }
            }),
        )
        qs('#qNext', root).addEventListener('click', () => {
            audio.blip()
            goTo('close')
        })
    },
}
