/**
 * PUNTO DE ENTRADA
 * 1. Importa los pasos (cada archivo de steps/ se registra solo en `steps`).
 * 2. Construye la escena 3D mostrando la pantalla de carga.
 * 3. Arranca el bucle de animacion (frame) y abre el paso 'home'.
 */
import { audio } from './audio/audio.js'
import { state } from './core/state.js'
import { damp, qs } from './core/utils.js'

// Pasos de la experiencia, en orden de aparicion (ver steps/navigation.js)
import './steps/intro.js'
import './steps/before.js'
import './steps/antesEnd.js'
import './steps/during.js'
import './steps/sizes.js'
import './steps/after.js'
import './steps/ending.js'

import { goTo, steps } from './steps/navigation.js'
import { fovBoost, updateCamera } from './systems/camera.js'
import { updateBeacon, updatePrompt } from './systems/interaction.js'
import { player, updatePlayer } from './systems/player.js'
import { updateQuake } from './systems/quake.js'
import { tourFovOffset } from './systems/scrollTour.js'
import { createDebris, updateBooks, updateDebris, updateQuakeEffects } from './systems/quakeEffects.js'
import { createCharacters, updateCharacters } from './three/characters.js'
import { camera, renderer, resize } from './three/renderer.js'
import { buildShowrooms, layoutSizes } from './three/showrooms.js'
import { loadLivingRoom, updateLivingRoom } from './three/livingRoom.js'
import { buildHouse } from './three/world.js'
import { updateBanner } from './ui/banner.js'
import './ui/controls.js'
import { positionTip, updateHotspots } from './ui/hotspots.js'
import { buildSeismo, updateSeismo } from './ui/seismo.js'

// Atajo para depurar: en la consola escribe  petalert.goTo('quiz')  para saltar a un paso.
window.petalert = { goTo, steps, state, player }

// Campo de vision base de cada modo de camara (el zoom de la transicion se suma encima).
const BASE_FOV = { fp: 68, show: 36, stage: 36, cine: 50, orbit: 34, tp: 34 }

let lastFrame = performance.now()
let fovEase = 0 // segundos que quedan de suavizado del campo de vision al salir del escenario

/** Un cuadro de animacion: actualiza todos los sistemas y dibuja. */
function frame(now) {
    const dt = Math.min(0.05, (now - lastFrame) / 1000)
    lastFrame = now
    state.time += dt

    // Logica
    updatePlayer(dt)
    if (state.curTick) {
        state.curTick(dt)
    }
    updateQuake(dt)
    updateBooks(dt)
    updateDebris(dt)
    updateQuakeEffects(dt)
    updateBeacon(dt)
    updateCharacters(dt)
    updateLivingRoom(dt)
    updateCamera(dt)

    // Zoom de la transicion de reinicio
    fovBoost.v = damp(fovBoost.v, fovBoost.t, 3, dt)
    const fov = BASE_FOV[state.mode] + fovBoost.v * 26 + tourFovOffset()
    // en el escenario (kit y rastreo) el campo de vision se acomoda suave, para que no haya salto al entrar o salir
    const smooth = state.mode === 'stage' || state.mode === 'cine'
    const nextFov = smooth || fovEase > 0 ? damp(camera.fov, fov, 3, dt) : fov
    if (fovEase > 0) fovEase -= dt
    if (smooth) fovEase = 1.6
    if (Math.abs(camera.fov - nextFov) > 0.02) {
        camera.fov = nextFov
        camera.updateProjectionMatrix()
    }

    // Interfaz
    updateSeismo(dt)
    updatePrompt()
    updateBanner()

    // Dibujo
    renderer.render(state.scene, camera)
    updateHotspots()
    positionTip()
    requestAnimationFrame(frame)
}

const pause = (ms = 60) => new Promise((resolve) => setTimeout(resolve, ms))

/** Construye todo en fases para poder mostrar la barra de carga. */
async function boot() {
    const bar = qs('#loadBar')
    const message = qs('#loaderMsg')
    resize()
    buildSeismo()
    try {
        bar.style.width = '15%'
        await pause()
        buildHouse()
        createDebris()

        bar.style.width = '45%'
        message.textContent = 'Cargando la sala…'
        await loadLivingRoom()

        bar.style.width = '60%'
        message.textContent = 'Acomodando a las mascotas…'
        await pause()
        createCharacters()

        bar.style.width = '75%'
        message.textContent = 'Guardando el kit de emergencia…'
        await pause()
        buildShowrooms()
        layoutSizes(null)

        bar.style.width = '100%'
        message.textContent = 'Todo listo'
        await pause(500)
    } catch (error) {
        message.textContent = 'Ocurrió un error al preparar la escena. Recarga la página.'
        console.error(error)
        return
    }
    requestAnimationFrame(frame)
    audio.init() // prepara el audio: la musica de la portada suena en cuanto el navegador lo permite
    goTo('home')
    qs('#loader').classList.add('out')
    setTimeout(() => {
        qs('#loader').hidden = true
    }, 800)
}

boot()
