/**
 * AUDIO: todo el sonido se genera con Web Audio (sin archivos).
 * Musica por estados de animo (calm, tense, hope, close), efectos y alarma.
 */
export const audio = {
    ctx: null,
    on: true,
    master: null,
    rumbleG: null,
    noiseBuf: null,
    init() {
        if (this.ctx) {
            if (this.ctx.state === 'suspended') {
                this.ctx.resume()
            }
            return
        }
        try {
            let e = window.AudioContext || window.webkitAudioContext
            if (!e) return
            let t = (this.ctx = new e())
            this.master = t.createGain()
            this.master.gain.value = this.on ? 1 : 0
            this.master.connect(t.destination)
            let a = t.sampleRate * 2,
                o = t.createBuffer(1, a, t.sampleRate),
                s = o.getChannelData(0),
                r = 0
            for (let p = 0; p < a; p++) {
                r = (r + 0.02 * (Math.random() * 2 - 1)) / 1.02
                s[p] = r * 3.5
            }
            this.noiseBuf = o
            let i = t.createBufferSource()
            i.buffer = o
            i.loop = true
            let n = t.createBiquadFilter()
            n.type = 'lowpass'
            n.frequency.value = 150
            this.rumbleG = t.createGain()
            this.rumbleG.gain.value = 0
            let d = t.createGain()
            d.gain.value = 0.75
            let u = t.createOscillator()
            u.frequency.value = 6.5
            let h = t.createGain()
            h.gain.value = 0.25
            u.connect(h)
            h.connect(d.gain)
            u.start()
            i.connect(n)
            n.connect(this.rumbleG)
            this.rumbleG.connect(d)
            d.connect(this.master)
            i.start()
            this.musicInit()
        } catch {
            this.ctx = null
        }
    },
    musicOn: true,
    duckV: 1,
    mood: 'calm',
    mTimer: null,
    mNext: 0,
    mStep: 0,
    mBar: 0,
    mBus: null,
    mIn: null,
    mLast: 3,
    MOODS: {
        calm: {
            bpm: 78,
            vol: 1,
            pad: 'sine',
            p: 0.55,
            pulse: 0,
            scale: [72, 74, 76, 79, 81, 84, 86],
            ch: [
                [48, [60, 64, 67, 71]],
                [45, [57, 60, 64, 67]],
                [41, [57, 60, 65, 69]],
                [43, [59, 62, 67, 69]],
            ],
        },
        tense: {
            bpm: 120,
            vol: 0.9,
            pad: 'sawtooth',
            p: 0.2,
            pulse: 2,
            riser: 1,
            scale: [81, 82, 84, 87, 88],
            ch: [
                [33, [57, 60, 63, 66]],
                [34, [58, 61, 64, 67]],
                [32, [56, 59, 62, 65]],
                [40, [56, 59, 62, 65]],
            ],
        },
        // Tension suave para el durante: acordes oscuros y lentos, notas sueltas graves y un latido muy suave
        suspense: {
            bpm: 66,
            vol: 0.8,
            pad: 'triangle',
            p: 0.2,
            pulse: 3,
            scale: [57, 58, 60, 63, 65, 69],
            ch: [
                [38, [57, 60, 63, 69]],
                [37, [56, 60, 62, 68]],
                [35, [59, 62, 65, 68]],
                [36, [58, 61, 64, 67]],
            ],
        },
        // Para los tamanos: tranquila y pensativa (menos alegre), en tono menor y con pocas notas sueltas
        sizes: {
            bpm: 78,
            vol: 0.8,
            pad: 'sine',
            p: 0.28,
            pulse: 0,
            scale: [69, 72, 74, 76, 79, 81],
            ch: [
                [45, [57, 60, 64, 69]],
                [41, [57, 60, 65, 69]],
                [43, [55, 59, 62, 67]],
                [40, [55, 59, 64, 67]],
            ],
        },
        hope: {
            bpm: 56,
            vol: 0.85,
            pad: 'sine',
            p: 0.24,
            pulse: 0,
            scale: [66, 69, 71, 74, 76, 78],
            ch: [
                [38, [62, 66, 69, 73]],
                [35, [59, 62, 66, 69]],
                [43, [55, 59, 62, 66]],
                [45, [57, 61, 64, 69]],
            ],
        },
        close: {
            bpm: 64,
            vol: 0.9,
            pad: 'sine',
            p: 0.4,
            pulse: 0,
            scale: [72, 74, 76, 79, 81, 84],
            ch: [
                [48, [60, 64, 67, 71]],
                [41, [57, 60, 65, 69]],
                [45, [57, 60, 64, 67]],
                [43, [59, 62, 67, 69]],
            ],
        },
    },
    mtof(e) {
        return 440 * Math.pow(2, (e - 69) / 12)
    },
    musicInit() {
        let e = this.ctx
        this.mIn = e.createGain()
        this.mBus = e.createGain()
        this.mBus.gain.value = this.musicOn ? 0.5 * this.duckV : 0
        this.mBus.connect(this.master)
        let t = Math.floor(e.sampleRate * 2),
            a = e.createBuffer(2, t, e.sampleRate)
        for (let r = 0; r < 2; r++) {
            let i = a.getChannelData(r)
            for (let n = 0; n < t; n++) i[n] = (Math.random() * 2 - 1) * Math.pow(1 - n / t, 2.6)
        }
        let o = e.createConvolver()
        o.buffer = a
        let s = e.createGain()
        s.gain.value = 0.55
        this.mIn.connect(this.mBus)
        this.mIn.connect(o)
        o.connect(s)
        s.connect(this.mBus)
        this.mNext = e.currentTime + 0.15
        this.mStep = 0
        this.mBar = 0
        clearInterval(this.mTimer)
        this.mTimer = setInterval(() => this.musicTick(), 90)
    },
    setMood(e) {
        if (this.MOODS[e] && e !== this.mood) {
            this.mood = e
            this.mBar = 0
            this.mStep = 0
            if (this.ctx) {
                this.mNext = Math.max(this.mNext, this.ctx.currentTime + 0.1)
            }
        }
    },
    duck(e) {
        this.duckV = e
        if (this.mBus) {
            this.mBus.gain.setTargetAtTime(this.musicOn ? 0.5 * e : 0, this.ctx.currentTime, 0.4)
        }
    },
    toggleMusic() {
        // si la musica aun no estaba sonando (el navegador espera un toque para permitirlo), este toque la inicia y queda activa
        const wasPlaying = this.playing
        this.init()
        if (!wasPlaying) return this.musicOn
        if (this.ctx.state === 'suspended') this.ctx.resume()
        this.musicOn = !this.musicOn
        if (this.mBus) {
            this.mBus.gain.setTargetAtTime(this.musicOn ? 0.5 * this.duckV : 0, this.ctx.currentTime, 0.15)
        }
        return this.musicOn
    },
    playing: false, // true cuando el audio ya esta corriendo (el navegador lo permitio)
    musicTick() {
        let e = this.ctx
        this.playing = !!e && e.state === 'running'
        if (!(!e || e.state !== 'running'))
            for (
                this.mNext < e.currentTime - 0.5 && (this.mNext = e.currentTime + 0.05);
                this.mNext < e.currentTime + 0.5;
            ) {
                this.musicStep(this.mNext)
                let t = this.MOODS[this.mood]
                this.mNext += 60 / t.bpm / 2
                this.mStep = (this.mStep + 1) % 8
                if (this.mStep === 0) {
                    this.mBar++
                }
            }
    },
    musicStep(e) {
        let t = this.MOODS[this.mood],
            a = 60 / t.bpm / 2,
            o = a * 8,
            s = this.mStep,
            r = t.ch[this.mBar % t.ch.length]
        if (s === 0) {
            // primer tiempo del compas: nota grave + acorde (cada nota ligeramente desafinada)
            this.mNote(r[0] + 0, e, o * 0.95, 'sine', 0.16 * t.vol, 0.05, o * 0.4)
            r[1].forEach((i, n) => {
                ;[-5, 5].forEach((d) =>
                    this.mNote(i, e + n * 0.03, o * 1.15, t.pad, 0.045 * t.vol, o * 0.35, o * 0.5, d),
                )
            })
        }
        if (t.pulse === 2) {
            let i = this.mtof(r[0])
            if (s % 4 === 0) {
                this.mThump(i, e, 0.42 * t.vol)
            } else if (s % 4 === 1) {
                this.mThump(i, e + a * 0.35, 0.26 * t.vol)
            }
            if (s === 0) {
                this.mNote(r[0] + 12, e, o * 0.95, 'sawtooth', 0.03 * t.vol, o * 0.5, o * 0.3)
                if (this.mBar % 4 === 3) {
                    this.mRiser(e, o)
                }
            }
        } else if (t.pulse === 3) {
            if (s % 4 === 0) this.mThump(this.mtof(r[0]), e, 0.16 * t.vol) // latido suave, dos por compas
        } else if (t.pulse && s % 2 === 0) {
            let i = this.mtof(r[0])
            this.mThump(i, e, 0.32 * t.vol)
        }
        if (Math.random() < t.p) {
            let i = this.mLast + Math.floor(Math.random() * 3) - 1
            i = Math.max(0, Math.min(t.scale.length - 1, i))
            this.mLast = i
            let n = t.scale[i]
            this.mNote(n, e, a * 5, 'triangle', 0.07 * t.vol, 0.008, a * 4.5)
            this.mNote(n + 12, e, a * 2.5, 'sine', 0.02 * t.vol, 0.005, a * 2)
        }
    },
    mNote(e, t, a, o, s, r, i, n) {
        let d = this.ctx,
            u = d.createOscillator(),
            h = d.createGain()
        u.type = o
        u.frequency.value = this.mtof(e)
        if (n) {
            u.detune.value = n
        }
        h.gain.setValueAtTime(1e-4, t)
        h.gain.linearRampToValueAtTime(s, t + Math.max(0.005, r))
        h.gain.setTargetAtTime(1e-4, t + Math.max(r + 0.01, a - i), Math.max(0.05, i * 0.35))
        if (o === 'sawtooth') {
            let p = d.createBiquadFilter()
            p.type = 'lowpass'
            p.frequency.value = 650
            u.connect(p)
            p.connect(h)
        } else u.connect(h)
        h.connect(this.mIn)
        u.start(t)
        u.stop(t + a + i * 0.6 + 0.2)
    },
    mRiser(e, t) {
        let a = this.ctx,
            o = a.createBufferSource()
        o.buffer = this.noiseBuf
        let s = a.createBiquadFilter()
        s.type = 'bandpass'
        s.Q.value = 2.5
        s.frequency.setValueAtTime(350, e)
        s.frequency.exponentialRampToValueAtTime(4200, e + t)
        let r = a.createGain()
        r.gain.setValueAtTime(1e-4, e)
        r.gain.exponentialRampToValueAtTime(0.09, e + t * 0.95)
        r.gain.exponentialRampToValueAtTime(1e-4, e + t + 0.05)
        o.connect(s)
        s.connect(r)
        r.connect(this.mIn)
        o.start(e, Math.random())
        o.stop(e + t + 0.1)
    },
    swell() {
        if (!this.ctx || !this.mIn) return
        let e = this.ctx,
            t = e.currentTime + 0.05
        this.mRiser(t, 1.8)
        ;[48, 55, 60, 64, 67, 72, 76].forEach((a, o) =>
            this.mNote(a, t + 1.8 + o * 0.04, 5, 'triangle', 0.07, 0.05, 3.6),
        )
        this.tone(60, 30, 1.4, 'sine', 0.3, 1.8)
    },
    whoosh() {
        if (!this.ctx) return
        let e = this.ctx,
            t = e.currentTime,
            a = e.createBufferSource()
        a.buffer = this.noiseBuf
        let o = e.createBiquadFilter()
        o.type = 'bandpass'
        o.Q.value = 1.4
        o.frequency.setValueAtTime(250, t)
        o.frequency.exponentialRampToValueAtTime(5e3, t + 1.2)
        let s = e.createGain()
        s.gain.setValueAtTime(1e-4, t)
        s.gain.exponentialRampToValueAtTime(0.32, t + 1)
        s.gain.exponentialRampToValueAtTime(1e-4, t + 1.7)
        a.connect(o)
        o.connect(s)
        s.connect(this.master)
        a.start(t, Math.random())
        a.stop(t + 1.8)
        this.tone(220, 880, 1.2, 'sine', 0.09)
        ;[523, 659, 784, 1047].forEach((r, i) =>
            this.tone(r, r * 1.005, 0.9, 'triangle', 0.06, 1.3 + i * 0.07),
        )
    },
    mThump(e, t, a) {
        let o = this.ctx,
            s = o.createOscillator(),
            r = o.createGain()
        s.type = 'sine'
        s.frequency.setValueAtTime(e * 2, t)
        s.frequency.exponentialRampToValueAtTime(e, t + 0.12)
        r.gain.setValueAtTime(1e-4, t)
        r.gain.exponentialRampToValueAtTime(a, t + 0.02)
        r.gain.exponentialRampToValueAtTime(1e-4, t + 0.5)
        s.connect(r)
        r.connect(this.mIn)
        s.start(t)
        s.stop(t + 0.6)
    },
    rumble(e) {
        if (this.ctx) {
            this.rumbleG.gain.setTargetAtTime(e, this.ctx.currentTime, 0.25)
        }
    },
    tone(e, t, a, o, s, r) {
        if (!this.ctx) return
        let i = this.ctx,
            n = i.currentTime + (r || 0),
            d = i.createOscillator(),
            u = i.createGain()
        d.type = o || 'sine'
        d.frequency.setValueAtTime(e, n)
        d.frequency.exponentialRampToValueAtTime(Math.max(20, t), n + a)
        u.gain.setValueAtTime(1e-4, n)
        u.gain.exponentialRampToValueAtTime(s || 0.1, n + 0.02)
        u.gain.exponentialRampToValueAtTime(1e-4, n + a)
        d.connect(u)
        u.connect(this.master)
        d.start(n)
        d.stop(n + a + 0.05)
    },
    noise(e, t, a) {
        if (!this.ctx) return
        let o = this.ctx,
            s = o.currentTime,
            r = o.createBufferSource()
        r.buffer = this.noiseBuf
        let i = o.createBiquadFilter()
        i.type = 'bandpass'
        i.frequency.value = t
        let n = o.createGain()
        n.gain.setValueAtTime(a, s)
        n.gain.exponentialRampToValueAtTime(1e-4, s + e)
        r.connect(i)
        i.connect(n)
        n.connect(this.master)
        r.start(s, Math.random())
        r.stop(s + e + 0.05)
    },
    blip() {
        this.tone(620, 860, 0.09, 'sine', 0.07)
    },
    // tic muy leve para la cuenta regresiva de los ultimos segundos
    tick() {
        this.tone(1000, 900, 0.09, 'sine', 0.07)
    },
    ding() {
        this.tone(880, 1320, 0.25, 'triangle', 0.09)
    },
    ok() {
        ;[523, 659, 784].forEach((e, t) => this.tone(e, e * 1.01, 0.3, 'triangle', 0.09, t * 0.09))
    },
    no() {
        this.tone(230, 160, 0.25, 'sawtooth', 0.05)
    },
    crash() {
        this.noise(0.4, 700, 0.3)
        this.tone(90, 40, 0.4, 'sine', 0.25)
    },
    creak() {
        this.tone(180, 120, 0.5, 'sawtooth', 0.03)
    },
    alarmSet(e) {
        if (!this.ctx) return
        let t = this.ctx
        if (!this.alG) {
            let a = t.createOscillator()
            a.type = 'square'
            a.frequency.value = 980
            let o = t.createOscillator()
            o.type = 'square'
            o.frequency.value = 2.2
            let s = t.createGain()
            s.gain.value = 190
            o.connect(s)
            s.connect(a.frequency)
            let r = t.createBiquadFilter()
            r.type = 'lowpass'
            r.frequency.value = 2400
            this.alG = t.createGain()
            this.alG.gain.value = 0
            a.connect(r)
            r.connect(this.alG)
            this.alG.connect(this.master)
            a.start()
            o.start()
        }
        this.alG.gain.setTargetAtTime(e, t.currentTime, 0.08)
    },
    thud() {
        this.noise(0.14, 420, 0.09)
        this.tone(130, 60, 0.16, 'sine', 0.1)
    },
    whimper() {
        this.tone(700, 420, 0.4, 'sine', 0.09)
        this.tone(650, 380, 0.45, 'sine', 0.08, 0.5)
    },
    meow() {
        this.tone(500, 900, 0.25, 'triangle', 0.09)
        this.tone(900, 550, 0.35, 'triangle', 0.09, 0.22)
    },
    bark() {
        this.tone(320, 180, 0.12, 'sawtooth', 0.07)
        this.tone(320, 180, 0.12, 'sawtooth', 0.07, 0.18)
    },
    toggle() {
        this.on = !this.on
        if (this.master) {
            this.master.gain.setTargetAtTime(this.on ? 1 : 0, this.ctx.currentTime, 0.05)
        }
        return this.on
    },
}
