/**
 * PLANTILLAS de paso reutilizables: recorrido por hotspots y panel centrado.
 */
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { icon } from '../data/icons.js'
import { focusOn } from '../systems/camera.js'
import { addHotspot } from '../ui/hotspots.js'
import { showPanel } from '../ui/panels.js'

/**
 * Recorrido por hotspots: el usuario toca cada punto 3D y ve una tarjeta con su informacion.
 * Nada avanza solo: el usuario lee a su ritmo y pasa con "Siguiente".
 *
 * config:
 *   title, text      cabecera del panel
 *   items            [{ anchor, title, text, icon, rot }]
 *   zoom             distancia de la camara al acercarse a un punto
 *   onPick(i)        i = punto abierto, o -1 al volver a la vista general
 *   next()           paso siguiente (boton "Continuar" del panel, se activa al ver todos los puntos)
 *   backLabel        texto del unico boton de cada tarjeta (vuelve a la vista general, para escoger otro punto)
 *   autoNext         true = cada punto se marca como visto al cerrarlo (y se avisa con onSeen(i)).
 *   openFirst        true = abre el primer punto al entrar (sin temporizadores).
 *
 * Devuelve { buttons, seen, opened } (los botones de los hotspots y los puntos ya vistos/abiertos).
 */
export function startInfoTour(config) {
    const total = config.items.length
    const opened = new Set() // puntos que el usuario ya abrio
    const seen = new Set() // puntos que ya cerro (autoNext)
    const buttons = []
    const stepName = state.cur // para ignorar llamadas tardias si el usuario ya cambio de paso
    const panel = showPanel({
        title: config.title,
        text: config.text,
        html: '<p class="count"></p>',
        actions: [{ label: 'Continuar', fn: config.next }],
    })
    const count = qs('.count', panel)
    const tip = qs('#tip')

    // Continuar siempre esta disponible: si falta algo por ver, solo se avisa cuantos faltan
    const updateCount = () => {
        const n = config.autoNext ? seen.size : opened.size
        const missing = total - n
        count.textContent =
            missing > 0
                ? 'Faltan ' + missing + ' por descubrir · toca un punto para acercarte'
                : 'Ya descubriste los ' + total
    }
    // Cierra la tarjeta y vuelve a la vista general.
    const showAll = () => {
        state.tipState = null
        tip.hidden = true
        panel.hidden = false
        qs('#hotspots').style.visibility = ''
        buttons.forEach((b) => b.classList.remove('on'))
        focusOn(null)
        if (config.onPick) config.onPick(-1)
        updateCount()
    }
    // Marca un punto como visto (al dejar de mirarlo).
    // onSeen puede devolver los milisegundos que dura su animacion (p. ej. guardar el objeto):
    // la tarjeta se oculta y el flujo continua cuando termina.
    const markSeen = (i) => {
        if (!config.autoNext || seen.has(i)) return 0
        seen.add(i)
        return (config.onSeen && config.onSeen(i)) || 0
    }
    const afterSeen = (wait, fn) => {
        if (!wait) return fn()
        state.tipState = null
        tip.hidden = true
        setTimeout(() => state.cur === stepName && fn(), wait)
    }
    const open = (i) => {
        const item = config.items[i]
        opened.add(i)
        buttons.forEach((b, k) => b.classList.toggle('on', i === k))
        buttons[i].classList.add('seen')
        if (config.onPick) config.onPick(i)
        focusOn(item.anchor, config.zoom, item.rot)
        panel.hidden = true
        qs('#hotspots').style.visibility = 'hidden'
        tip.innerHTML =
            '<div class="num">' +
            (i + 1) +
            ' de ' +
            total +
            '</div>' +
            '<div class="ttl"><span class="ico">' +
            icon(item.icon) +
            '</span><h3>' +
            item.title +
            '</h3></div>' +
            '<p>' +
            item.text +
            '</p>' +
            // un solo boton: volver a la vista general para escoger otro
            '<div class="row"><button class="btn" data-a="all">' +
            (config.backLabel || 'Ver otros') +
            '</button></div>'
        tip.hidden = false
        state.tipState = { anchor: item.anchor }
        qs('[data-a=all]', tip).addEventListener('click', () => {
            audio.blip()
            afterSeen(markSeen(i), showAll)
        })
        audio.ding()
        updateCount()
    }
    config.items.forEach((item, i) =>
        buttons.push(addHotspot({ anchor: item.anchor, aria: item.title, onClick: () => open(i) })),
    )
    updateCount()
    if (config.openFirst) setTimeout(() => state.cur === stepName && open(0), 900)
    return { buttons, seen, opened }
}
export function showCenterPanel(text, label, onNext, extraClass) {
    showPanel({
        text: text,
        cls: 'center' + (extraClass || ''),
        actions: [
            {
                label: label || 'Continuar',
                fn: onNext,
            },
        ],
    })
}
