/**
 * LINEA DE TIEMPO (arriba): un sismograma ordenado. Los picos suben y bajan de forma regular, con lineas rectas,
 * y su altura crece hacia el "Durante" y se calma hacia el "Cierre". Se llena con el progreso.
 */
import { clamp, damp, qs, qsa } from '../core/utils.js'

const WIDTH = 460 // ancho del viewBox del svg
const MID = 15 // altura de la linea central (el viewBox mide 30 de alto)
const POINTS = 92 // un vertice cada 5 unidades: pico arriba, pico abajo...
// Altura de los picos segun el avance (0 a 1): recta en el inicio, empieza a variar en el antes,
// es maxima en el durante y se calma hacia el cierre
const ENVELOPE = [
    [0, 0],
    [0.2, 0],
    [0.3, 1.8],
    [0.4, 5],
    [0.5, 12],
    [0.6, 13],
    [0.75, 6],
    [0.9, 2],
    [1, 0.8],
]
const seismo = {
    len: 1,
    p: 0,
    tp: 0,
}
function amplitudeAt(d) {
    for (let i = 1; i < ENVELOPE.length; i++) {
        const [x1, y1] = ENVELOPE[i]
        if (d <= x1) {
            const [x0, y0] = ENVELOPE[i - 1]
            return y0 + ((y1 - y0) * (d - x0)) / (x1 - x0)
        }
    }
    return ENVELOPE[ENVELOPE.length - 1][1]
}
export function buildSeismo() {
    let path = 'M0 ' + MID
    let prev = { x: 0, y: MID }
    seismo.cum = [0] // largo acumulado de la linea hasta cada vertice: asi el avance coincide con las etapas
    for (let i = 1; i <= POINTS; i++) {
        const d = i / POINTS
        const point = { x: d * WIDTH, y: MID + (i % 2 ? -1 : 1) * amplitudeAt(d) }
        seismo.cum.push(seismo.cum[i - 1] + Math.hypot(point.x - prev.x, point.y - prev.y))
        path += ' L' + point.x.toFixed(1) + ' ' + point.y.toFixed(1)
        prev = point
    }
    qs('#sBase').setAttribute('d', path)
    qs('#sFill').setAttribute('d', path)
    seismo.len = qs('#sFill').getTotalLength()
    qs('#sFill').style.strokeDasharray = seismo.len
    qs('#sFill').style.strokeDashoffset = seismo.len
}
export function updateSeismo(dt) {
    seismo.p = damp(seismo.p, seismo.tp, 3, dt)
    // el avance (0 a 1) es horizontal: se convierte al largo recorrido sobre la linea
    const pos = clamp(seismo.p, 0, 1) * POINTS
    const i = Math.min(POINTS - 1, Math.floor(pos))
    const length = seismo.cum[i] + (seismo.cum[i + 1] - seismo.cum[i]) * (pos - i)
    const scale = seismo.len / seismo.cum[POINTS]
    qs('#sFill').style.strokeDashoffset = seismo.len - length * scale
    const a = qs('#sFill').getPointAtLength(clamp(length * scale, 0.001, seismo.len))
    qs('#sDot').setAttribute('cx', a.x)
    qs('#sDot').setAttribute('cy', a.y)
}
export function setStage(stage, weight) {
    seismo.tp = (stage + weight) / 5
    qsa('#stages button').forEach((a, o) => {
        a.classList.toggle('on', o === stage)
        a.setAttribute('aria-current', o === stage ? 'step' : 'false')
    })
    qs('#seismo').setAttribute(
        'aria-label',
        'Progreso: etapa ' + ['Inicio', 'Antes', 'Durante', 'Después', 'Cierre'][stage],
    )
}
