/**
 * RECORRIDO POR SCROLL (primera persona).
 * El usuario no camina con teclas: el scroll (rueda, deslizar en pantalla tactil o flechas)
 * mueve la camara a lo largo de un camino hasta un objeto. Al acercarse, la camara se
 * endereza hacia el objeto, el campo de vision se cierra y aparece su titulo.
 *
 * Uso desde un paso:
 *   startTour({ path: [{ x, z }, ...], look: [x, y, z], onProgress: (p) => {...} })
 *   p va de 0 (inicio del camino) a 1 (frente al objeto).
 */
import * as THREE from 'three'
import {
    LOOK_RANGE_X,
    LOOK_RANGE_Y,
    EYE_HEIGHT,
    LOOK_UP,
    SCROLL_MAX_STEP,
    SCROLL_PX_PER_METER,
    SCROLL_SMOOTH_TIME,
    TOUR_CLOSE_FOV,
} from '../config.js'
import { clamp, damp } from '../core/utils.js'
import { camera } from '../three/renderer.js'
import { quietScrollHint, setTourProgress } from '../ui/hud.js'
import { player } from './player.js'

export const tour = {
    active: false,
    locked: false, // true = el scroll ya no mueve la camara (p. ej. durante la caricia)
    progress: 0, // posicion actual (suavizada)
    vel: 0, // velocidad del resorte
    target: 0, // posicion que pide el scroll
    length: 1, // largo del camino en metros
    curve: null,
    look: new THREE.Vector3(), // objeto que se mira al final
    entryLook: null,
    lookAtStart: null,
    intro: null,
    closeFrom: 0.7, // desde aqui la camara empieza a girar hacia el objeto
    eye: EYE_HEIGHT, // altura de los ojos
    closeness: 0, // 0 = caminando, 1 = frente al objeto
    bob: 0,
    mx: 0, // posicion del puntero (-1..1)
    my: 0,
    lookX: 0, // puntero suavizado
    lookY: 0,
    onProgress: null,
}

const here = new THREE.Vector3()
const ahead = new THREE.Vector3()
const aim = new THREE.Vector3()
const lastAim = new THREE.Vector3()
const tmp = new THREE.Vector3()
const dir = new THREE.Vector3()
const lastDir = new THREE.Vector3(1, 0, 0)
const smooth = (a, b, x) => {
    const k = clamp((x - a) / (b - a), 0, 1)
    return k * k * (3 - 2 * k)
}

/** Resorte critico (como SmoothDamp): arranca y frena con suavidad, sin saltos. */
function smoothDamp(obj, target, smoothTime, dt) {
    const omega = 2 / smoothTime
    const x = omega * dt
    const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x)
    const change = obj.progress - target
    const temp = (obj.vel + omega * change) * dt
    obj.vel = (obj.vel - omega * temp) * decay
    return target + (change + temp) * decay
}

export function startTour({
    path,
    look,
    startAt = 0,
    closeFrom = 0.7,
    continueLook = false,
    lookDown = 0.55,
    lookAtStart = null,
    introFrom = null,
    introTime = 1.8,
    onProgress,
}) {
    tour.curve = new THREE.CatmullRomCurve3(
        path.map((p) => new THREE.Vector3(p.x, 0, p.z)),
        false,
        'centripetal',
    )
    tour.length = tour.curve.getLength()
    // continueLook: el recorrido empieza mirando donde miraba el anterior y gira hacia el nuevo objeto
    tour.entryLook = continueLook ? lastAim.clone() : null
    tour.look.set(look[0], look[1], look[2])
    tour.closeFrom = closeFrom
    // lookAtStart: al empezar mira hacia ese punto (p. ej. las mascotas) y luego gira hacia el camino
    tour.lookAtStart = lookAtStart ? new THREE.Vector3(...lookAtStart) : null
    // introFrom: al empezar la camara gira sola desde ese punto (durante introTime s el scroll no la mueve)
    tour.intro = introFrom ? { from: new THREE.Vector3(...introFrom), t: 0, dur: introTime } : null
    tour.lookDown = lookDown // cuanto baja la mirada hacia el objeto (0 = recta, 1 = directo al objeto)
    tour.progress = tour.target = startAt
    tour.vel = 0
    tour.closeness = 0
    tour.onProgress = onProgress || null
    tour.active = true
    tour.locked = !!tour.intro
    setTourProgress(startAt, 0)
}

/** Congela la camara donde esta (el scroll deja de moverla). */
export function lockTour() {
    tour.locked = true
    tour.target = tour.progress
    quietScrollHint()
}

export function stopTour() {
    tour.active = false
    tour.onProgress = null
    tour.closeness = 0
    player.moving = false
    setTourProgress(0, 0)
}

/** Avanza (+) o retrocede (-) el recorrido; `px` son pixeles de scroll. */
export function nudgeTour(px) {
    if (!tour.active || tour.locked) return
    if (px > 0) quietScrollHint()
    px = clamp(px, -SCROLL_MAX_STEP, SCROLL_MAX_STEP) // limita saltos de ruedas muy rapidas
    tour.target = clamp(tour.target + px / (tour.length * SCROLL_PX_PER_METER), 0, 1)
}

/** Cuanto se cierra el campo de vision al acercarse (se suma al fov base). */
export function tourFovOffset() {
    return tour.active ? tour.closeness * TOUR_CLOSE_FOV : 0
}

/** Coloca la camara cada cuadro. Lo llama updateCamera cuando el recorrido esta activo. */
export function updateTour(dt) {
    const before = tour.progress
    tour.progress = smoothDamp(tour, tour.target, SCROLL_SMOOTH_TIME, dt)
    if (Math.abs(tour.target - tour.progress) < 0.0002 && Math.abs(tour.vel) < 0.002) {
        tour.progress = tour.target
        tour.vel = 0
    }
    const p = tour.progress

    tour.curve.getPointAt(p, here)
    tour.curve.getPointAt(Math.min(1, p + 0.04), ahead)

    // Direccion horizontal del camino (se recuerda al final, donde el camino se acaba)
    dir.set(ahead.x - here.x, 0, ahead.z - here.z)
    if (dir.lengthSq() > 1e-6) lastDir.copy(dir.normalize())

    // Mirando de frente: vista recta, un poco hacia arriba. Al acercarse, gira hacia el objeto
    // (en horizontal del todo; en vertical solo en parte para que la vista siga natural).
    const w = smooth(tour.closeFrom, 0.97, p)
    tour.closeness = w
    const eyeY = tour.eye
    aim.set(here.x + lastDir.x * 6, eyeY + LOOK_UP * 6, here.z + lastDir.z * 6)
    aim.x += (tour.look.x - aim.x) * w
    aim.z += (tour.look.z - aim.z) * w
    aim.y += (tour.look.y - aim.y) * w * tour.lookDown
    if (tour.entryLook) {
        aim.lerpVectors(tour.entryLook, tour.look, smooth(0, 1, p))
        tour.closeness = 1
    }
    if (tour.lookAtStart) {
        tmp.copy(aim)
        aim.lerpVectors(tour.lookAtStart, tmp, smooth(0.02, 0.3, p))
    }
    if (tour.intro) {
        tour.intro.t += dt
        tmp.copy(aim)
        aim.lerpVectors(tour.intro.from, tmp, smooth(0, 1, tour.intro.t / tour.intro.dur))
        if (tour.intro.t >= tour.intro.dur) {
            tour.intro = null
            tour.locked = false
        }
    }
    lastAim.copy(aim)

    const speed = (Math.abs(p - before) * tour.length) / Math.max(dt, 1e-3) // m/s
    tour.bob += dt * 9 * Math.min(1, speed / 2)
    const bob = Math.sin(tour.bob) * 0.03 * Math.min(1, speed / 2) * (1 - w)
    camera.position.set(here.x, tour.eye + bob, here.z)
    camera.lookAt(aim)
    // La camara sigue al puntero: gira a los lados y arriba/abajo (rango en config.js)
    // curva suave: con el puntero cerca del centro casi no gira, y solo en los bordes llega al maximo
    const soft = (v) => Math.sign(v) * Math.abs(v) ** 1.5
    tour.lookX = damp(tour.lookX, soft(tour.mx), 3, dt)
    tour.lookY = damp(tour.lookY, soft(tour.my), 3, dt)
    camera.rotateY(-tour.lookX * LOOK_RANGE_X)
    camera.rotateX(-tour.lookY * LOOK_RANGE_Y)

    player.pos.set(here.x, 0, here.z)
    player.moving = speed > 0.2
    setTourProgress(p, w)
    if (tour.onProgress) tour.onProgress(p)
}
